a8=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5591 > \ubcf5\uc18c\uc218 > \uc2e4\uc218\uc640\ud5c8\uc218 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.q,A.a(['[   "\uc6b0\ub9ac\uac00 \ud754\ud788 \uc0ac\uc6a9\ud558\ub294 \uc218\uc778 \uc2e4\uc218(real number)\ub294 \uc81c\uacf1\ud558\uba74 \ud56d\uc0c1 0\ubcf4\ub2e4 \ud06c\uac70\ub098 \uac19\uc740 \uc131\uc9c8\uc744 \uac00\uc9d1\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc218\ud559\uc790\ub4e4\uc740 \uc81c\uacf1\ud558\uc5ec \uc74c\uc218\uac00 \ub418\ub294 \uc0c8\ub85c\uc6b4 \uc218\uc758 \ud544\uc694\uc131\uc744 \ub290\uaf08\uace0, \uc774\ub97c \uc704\ud574 \uc81c\uacf1\ud558\uc5ec $-1$\uc774 \ub418\ub294 \uc218 $i$\ub97c \ub3c4\uc785\ud558\uc600\uc2b5\ub2c8\ub2e4. \uc5ec\uae30\uc11c $i$\ub294 \ud5c8\uc218 \ub2e8\uc704(imaginary unit)\ub77c\uace0 \ubd80\ub974\uba70, $i^2 = -1$\uc774\ub77c\ub294 \uc815\uc758\ub97c \uac00\uc9d1\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc2e4\uc218\uc640 \ud5c8\uc218\ub97c \ud1b5\ud2c0\uc5b4 \ubcf5\uc18c\uc218(complex number)\ub77c\uace0 \ud558\uba70, \ubcf5\uc18c\uc218\ub294 \uc2e4\uc218\ubd80\uc640 \ud5c8\uc218\ubd80\ub85c \uad6c\uc131\ub429\ub2c8\ub2e4.",   "\ubcf5\uc18c\uc218\ub294 \uc77c\ubc18\uc801\uc73c\ub85c $a + bi$ (\ub2e8, $a, b$\ub294 \uc2e4\uc218)\uc758 \uaf34\ub85c \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \uc774\ub54c $a$\ub97c \uc2e4\uc218\ubd80\ubd84, $b$\ub97c \ud5c8\uc218\ubd80\ubd84\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \ub9cc\uc57d $b=0$\uc774\uba74 \uc774 \ubcf5\uc18c\uc218\ub294 \uc2e4\uc218\uac00 \ub418\uace0, $b \\neq 0$\uc774\uba74 \ud5c8\uc218\uac00 \ub429\ub2c8\ub2e4. \ud2b9\ud788 $a=0$\uc774\uace0 $b \\neq 0$\uc778 \uacbd\uc6b0\ub97c \uc21c\ud5c8\uc218\ub77c\uace0 \ubd80\ub985\ub2c8\ub2e4. \ubcf5\uc18c\uc218\uc758 \uccb4\uacc4\uc5d0\uc11c \uc2e4\uc218\ub294 \ud5c8\uc218\ubd80\ubd84\uc774 0\uc778 \ud2b9\ubcc4\ud55c \uacbd\uc6b0\ub85c \ud3ec\ud568\ub418\uba70, \ubaa8\ub4e0 \uc2e4\uc218\ub294 \ubcf5\uc18c\uc218\uc758 \uc77c\ubd80\ubd84\uc785\ub2c8\ub2e4.",   "\ubcf5\uc18c\uc218\uc758 \uc5f0\uc0b0\uc5d0\uc11c \uac00\uc7a5 \uc911\uc694\ud55c \uc131\uc9c8\uc740 $i^2 = -1$\uc774\ub77c\ub294 \uc810\uc785\ub2c8\ub2e4. \ub450 \ubcf5\uc18c\uc218 $a+bi$\uc640 $c+di$\uac00 \uc11c\ub85c \uac19\uc744 \uc870\uac74\uc740 \uc2e4\uc218\ubd80\ubd84\ub07c\ub9ac \uac19\uace0($a=c$), \ud5c8\uc218\ubd80\ubd84\ub07c\ub9ac \uac19\uc544\uc57c($b=d$) \ud55c\ub2e4\ub294 \uac83\uc785\ub2c8\ub2e4. \ub610\ud55c, \ubcf5\uc18c\uc218 $z = a+bi$\uc5d0 \ub300\ud558\uc5ec $a-bi$\ub97c $z$\uc758 \ucf24\ub808\ubcf5\uc18c\uc218\ub77c\uace0 \ud558\uba70 $\\bar{z}$\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc131\uc9c8\ub4e4\uc744 \uc774\uc6a9\ud558\uba74 \ubcf5\uc18c\uc218\uc758 \ub367\uc148, \ube84\uc148, \uacf1\uc148, \ub098\ub217\uc148\uc744 \uc2e4\uc218\uc640 \uc720\uc0ac\ud558\uac8c \uacc4\uc0b0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.",   "\uc608\uc81c 1: \ub2e4\uc74c \ubcf5\uc18c\uc218 $(2 + 3i) + (1 - 4i)$\ub97c \uacc4\uc0b0\ud574 \ubd05\uc2dc\ub2e4. \ubcf5\uc18c\uc218\uc758 \ub367\uc148\uc740 \uc2e4\uc218\ubd80\ubd84\uc740 \uc2e4\uc218\ubd80\ubd84\ub07c\ub9ac, \ud5c8\uc218\ubd80\ubd84\uc740 \ud5c8\uc218\ubd80\ubd84\ub07c\ub9ac \ubaa8\uc544\uc11c \uacc4\uc0b0\ud558\uba74 \ub429\ub2c8\ub2e4. \uba3c\uc800 \uc2dd\uc744 \uc815\ub9ac\ud558\uba74 $(2+1) + (3i - 4i)$\uac00 \ub429\ub2c8\ub2e4. \uc774\ub97c \uacc4\uc0b0\ud558\uba74 \uc2e4\uc218\ubd80\ubd84\uc740 $2+1=3$\uc774 \ub418\uace0, \ud5c8\uc218\ubd80\ubd84\uc740 $3-4=-1$\uc774 \ub418\uc5b4 \ucd5c\uc885 \uacb0\uacfc\ub294 $$3 - i$$\uac00 \ub429\ub2c8\ub2e4.",   "\uc608\uc81c 2: \ubcf5\uc18c\uc218\uc758 \uacf1\uc148\uc778 $(1 + 2i)(3 - i)$\ub97c \uacc4\uc0b0\ud574 \ubd05\uc2dc\ub2e4. \ub2e4\ud56d\uc2dd\uc758 \uacf1\uc148\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c \ubd84\ubc30\ubc95\uce59\uc744 \uc0ac\uc6a9\ud558\uc5ec \uc804\uac1c\ud569\ub2c8\ub2e4. \uc2dd\uc744 \uc804\uac1c\ud558\uba74 $1 \\cdot 3 + 1 \\cdot (-i) + 2i \\cdot 3 + 2i \\cdot (-i)$\uac00 \ub429\ub2c8\ub2e4. \uc774\ub97c \uacc4\uc0b0\ud558\uba74 $3 - i + 6i - 2i^2$\uc774 \ub429\ub2c8\ub2e4. \uc5ec\uae30\uc11c $i^2 = -1$\uc784\uc744 \uc774\uc6a9\ud558\uba74 $-2i^2 = -2(-1) = 2$\uac00 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc2e4\uc218\ubd80\ubd84\uc740 $3+2=5$, \ud5c8\uc218\ubd80\ubd84\uc740 $-i+6i=5i$\uac00 \ub418\uc5b4 \ucd5c\uc885 \uacb0\uacfc\ub294 $$5 + 5i$$\uac00 \ub429\ub2c8\ub2e4." ]'],ai0),u6,B.o)],ai2),u6,B.o)],ai3),s3,s3,s3,"concept_\uc2e4\uc218\uc640\ud5c8\uc218",0,"","\uacf5\ud1b5\uc218\ud5591 > \ubcf5\uc18c\uc218 > \uc2e4\uc218\uc640\ud5c8\uc218",a8,u6,s3)
a9=A.a(["\uacf5\ud1b5\uc218\ud5592","\uc88c\ud45c\ud3c9\uba74","\ub450\uc9c1\uc120\uc758\uc704\uce58\uad00\uacc4","\uc77c\uce58\uc870\uac74"],ai0)
a9=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \ub450\uc9c1\uc120\uc758\uc704\uce58\uad00\uacc4 > \uc77c\uce58\uc870\uac74 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.q,A.a(["\uc88c\ud45c\ud3c9\uba74 \uc704\uc5d0\uc11c \ub450 \uc9c1\uc120\uc774 \uc11c\ub85c '\uc77c\uce58\ud55c\ub2e4'\ub294 \uac83\uc740 \ub450 \uc9c1\uc120\uc774 \ubaa8\ub4e0 \uc810\uc5d0\uc11c \ub9cc\ub09c\ub2e4\ub294 \uac83\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc989, \ud55c \uc9c1\uc120 \uc704\uc758 \ubaa8\ub4e0 \uc810\uc774 \ub2e4\ub978 \uc9c1\uc120 \uc704\uc5d0\ub3c4 \uc874\uc7ac\ud558\uc5ec \ub450 \uc9c1\uc120\uc774 \uc644\uc804\ud788 \uacb9\uccd0\uc9c0\ub294 \uc0c1\ud0dc\ub97c \ub9d0\ud569\ub2c8\ub2e4. \uc774\ub97c \uc218\uc2dd\uc73c\ub85c \ub098\ud0c0\ub0b4\uae30 \uc704\ud574 \ub450 \uc9c1\uc120\uc758 \ubc29\uc815\uc2dd\uc744 \uac01\uac01 $a_1x + b_1y + c_1 = 0$\uacfc $a_2x + b_2y + c_2 = 0$\uc774\ub77c\uace0 \uac00\uc815\ud574 \ubd05\uc2dc\ub2e4.","\ub450 \uc9c1\uc120\uc774 \uc77c\uce58\ud558\uae30 \uc704\ud574\uc11c\ub294 \uae30\uc6b8\uae30\uac00 \uac19\uc544\uc57c \ud560 \ubfd0\ub9cc \uc544\ub2c8\ub77c, $y$\uc808\ud3b8\uae4c\uc9c0 \uc644\uc804\ud788 \uac19\uc544\uc57c \ud569\ub2c8\ub2e4. \uc774\ub97c \uacc4\uc218\uc758 \ube44\ub97c \uc774\uc6a9\ud558\uc5ec \ud45c\ud604\ud558\uba74 \ub2e4\uc74c\uacfc \uac19\uc740 \uc77c\uce58 \uc870\uac74\uc744 \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub450 \uc9c1\uc120\uc774 \uc77c\uce58\ud560 \ud544\uc694\ucda9\ubd84\uc870\uac74\uc740 \uac01 \uacc4\uc218\uc758 \ube44\uac00 \ubaa8\ub450 \uac19\uc544\uc57c \ud55c\ub2e4\ub294 \uac83\uc774\uba70, \uc774\ub97c \uacf5\uc2dd\uc73c\ub85c \ub098\ud0c0\ub0b4\uba74 $$ \\frac{a_1}{a_2} = \\frac{b_1}{b_2} = \\frac{c_1}{c_2} $$ \uc640 \uac19\uc2b5\ub2c8\ub2e4.","\uc774 \uc870\uac74\uc740 \ub450 \uc9c1\uc120\uc758 \ubc29\uc815\uc2dd\uc774 \uc0ac\uc2e4\uc0c1 \uac19\uc740 \uc2dd\uc758 \ubc30\uc218 \uad00\uacc4\uc5d0 \uc788\uc74c\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \ud55c \uc9c1\uc120\uc758 \ubc29\uc815\uc2dd\uc5d0 0\uc774 \uc544\ub2cc \uc0c1\uc218 $k$\ub97c \uacf1\ud588\uc744 \ub54c \ub2e4\ub978 \uc9c1\uc120\uc758 \ubc29\uc815\uc2dd\uc774 \ub41c\ub2e4\uba74, \ub450 \uc9c1\uc120\uc740 \uc77c\uce58\ud558\uac8c \ub429\ub2c8\ub2e4. \uc989, $a_1 = ka_2$, $b_1 = kb_2$, $c_1 = kc_2$\ub97c \ub9cc\uc871\ud558\ub294 \uc0c1\uc218 $k$\uac00 \uc874\uc7ac\ud55c\ub2e4\uba74 \ub450 \uc9c1\uc120\uc740 \uc88c\ud45c\ud3c9\uba74\uc0c1\uc5d0\uc11c \ub3d9\uc77c\ud55c \uacbd\ub85c\ub97c \uc9c0\ub098\uac8c \ub429\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \ud655\uc778\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ub450 \uc9c1\uc120 $2x + 3y - 6 = 0$\uacfc $4x + 6y + k = 0$\uc774 \uc11c\ub85c \uc77c\uce58\ud560 \ub54c, \uc0c1\uc218 $k$\uc758 \uac12\uc744 \uad6c\ud558\ub294 \ubb38\uc81c\ub97c \ud480\uc5b4\ubd05\uc2dc\ub2e4. \ub450 \uc9c1\uc120\uc774 \uc77c\uce58\ud558\ub824\uba74 \uacc4\uc218\uc758 \ube44\uac00 \ubaa8\ub450 \uac19\uc544\uc57c \ud558\ubbc0\ub85c, \uacf5\uc2dd\uc5d0 \ub530\ub77c \ub2e4\uc74c\uacfc \uac19\uc740 \uc2dd\uc744 \uc138\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. $$ \\frac{2}{4} = \\frac{3}{6} = \\frac{-6}{k} $$","\uc704 \uc2dd\uc744 \ub2e8\uacc4\ubcc4\ub85c \uacc4\uc0b0\ud558\uba74 \uba3c\uc800 \uccab \ubc88\uc9f8\uc640 \ub450 \ubc88\uc9f8 \ud56d\uc5d0\uc11c $\\frac{2}{4} = \\frac{1}{2}$\uc774\uace0 $\\frac{3}{6} = \\frac{1}{2}$\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\uc81c \uc77c\uce58 \uc870\uac74\uc778 $\\frac{1}{2} = \\frac{-6}{k}$\ub97c \ub9cc\uc871\ud558\ub294 $k$\ub97c \ucc3e\uae30 \uc704\ud574 \uc591\ubcc0\uc5d0 $2k$\ub97c \uacf1\ud558\uc5ec \uc815\ub9ac\ud558\uba74 $k = 2 \\times (-6)$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \ucd5c\uc885\uc801\uc73c\ub85c $k = -12$\ub77c\ub294 \uac12\uc744 \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uacb0\uacfc\uc801\uc73c\ub85c $k = -12$\ub97c \ub300\uc785\ud558\uba74 \ub450 \ubc88\uc9f8 \uc9c1\uc120\uc758 \ubc29\uc815\uc2dd\uc740 $4x + 6y - 12 = 0$\uc774 \ub429\ub2c8\ub2e4. \uc774 \uc2dd\uc744 2\ub85c \ub098\ub204\uba74 $2x + 3y - 6 = 0$\uc774 \ub418\uc5b4 \uccab \ubc88\uc9f8 \uc9c1\uc120\uacfc \uc644\uc804\ud788 \uac19\uc544\uc9d0\uc744 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc77c\uce58 \uc870\uac74\uc740 \ub450 \uc9c1\uc120\uc758 \uacc4\uc218 \ube44\uc728\uc744 \ube44\uad50\ud568\uc73c\ub85c\uc368 \ub450 \uc9c1\uc120\uc774 \uac19\uc740 \uc9c1\uc120\uc778\uc9c0 \ud310\ubcc4\ud558\ub294 \ub9e4\uc6b0 \uc720\uc6a9\ud55c \ub3c4\uad6c\uac00 \ub429\ub2c8\ub2e4."],ai0),u7,B.o)],ai2),u7,B.o)],ai3),s3,s3,s3,"concept_\uc77c\uce58\uc870\uac74",0,"","\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \ub450\uc9c1\uc120\uc758\uc704\uce58\uad00\uacc4 > \uc77c\uce58\uc870\uac74",a9,u7,s3)
b0=A.a(["\ub300\uc218","\ub85c\uadf8","\ub85c\uadf8\uc758\uc131\uc9c8","\ubc11\uc758\ubcc0\ud658"],ai0)
b0=A.av(s2,A.a([A.au(A.a(["\ub300\uc218 > \ub85c\uadf8 > \ub85c\uadf8\uc758\uc131\uc9c8 > \ubc11\uc758\ubcc0\ud658 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.q,A.a(["\ub85c\uadf8\uc758 \ubc11\uc758 \ubcc0\ud658 \uacf5\uc2dd\uc740 \ub85c\uadf8\uc758 \ubc11\uc744 \uc6b0\ub9ac\uac00 \uc6d0\ud558\ub294 \uc0c8\ub85c\uc6b4 \ubc11\uc73c\ub85c \uc790\uc720\ub86d\uac8c \ubc14\uafc0 \uc218 \uc788\uac8c \ud574\uc8fc\ub294 \ub9e4\uc6b0 \uc720\uc6a9\ud55c \ub3c4\uad6c\uc785\ub2c8\ub2e4. \ub85c\uadf8 $\\log_a b$\uc5d0\uc11c \ubc11 $a$\uac00 \uacc4\uc0b0\ud558\uae30 \ubd88\ud3b8\ud558\uac70\ub098, \ub2e4\ub978 \ub85c\uadf8\ub4e4\uacfc \ubc11\uc744 \ud1b5\uc77c\ud574\uc57c \ud560 \ub54c \uc774 \uacf5\uc2dd\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uc784\uc758\uc758 \uc591\uc218 $c$ ($c \\neq 1$)\uc5d0 \ub300\ud558\uc5ec, \ub85c\uadf8\uc758 \ubc11\uc744 $c$\ub85c \ubc14\uafb8\ub294 \uacf5\uc2dd\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$ \\log_a b = \\frac{\\log_c b}{\\log_c a} $$","\uc774 \uacf5\uc2dd\uc758 \ud575\uc2ec\uc740 \uc6d0\ub798 \ub85c\uadf8\uc758 \uc9c4\uc218 $b$\ub294 \ubd84\uc790\ub85c, \uc6d0\ub798 \ub85c\uadf8\uc758 \ubc11 $a$\ub294 \ubd84\ubaa8\ub85c \uac00\ub418, \uc0c8\ub85c\uc6b4 \ubc11 $c$\ub97c \uac01\uac01\uc758 \ub85c\uadf8 \ubc11\uc73c\ub85c \ucde8\ud574\uc900\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4. \ud2b9\ud788, \uc6d0\ub798 \ub85c\uadf8\uc758 \uc9c4\uc218 $b$\ub97c \uc0c8\ub85c\uc6b4 \ubc11\uc73c\ub85c \uc124\uc815\ud558\uba74 \ub354\uc6b1 \uac04\ub2e8\ud55c \uc131\uc9c8\uc744 \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc989, $c=b$\ub97c \ub300\uc785\ud558\uba74 $\\log_a b = \\frac{\\log_b b}{\\log_b a}$\uac00 \ub418\ub294\ub370, $\\log_b b = 1$\uc774\ubbc0\ub85c \ub2e4\uc74c\uacfc \uac19\uc740 \uc5ed\uc218 \uad00\uacc4\uac00 \uc131\ub9bd\ud569\ub2c8\ub2e4. $$ \\log_a b = \\frac{1}{\\log_b a} $$","\ub610\ud55c, \ubc11\uc758 \ubcc0\ud658 \uacf5\uc2dd\uc744 \uc751\uc6a9\ud558\uba74 \ub85c\uadf8\ub07c\ub9ac\uc758 \uacf1\uc148\uc5d0\uc11c \ub9e4\uc6b0 \ud3b8\ub9ac\ud55c \uc131\uc9c8\uc744 \ubc1c\uacac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ubc11\uacfc \uc9c4\uc218\ub97c \uac00\uc9c4 \ub450 \ub85c\uadf8\uc758 \uacf1\uc740 \ub2e4\uc74c\uacfc \uac19\uc774 \uc815\ub9ac\ub429\ub2c8\ub2e4. $$ \\log_a b \\times \\log_b c = \\frac{\\log c}{\\log a} \\times \\frac{\\log b}{\\log b} = \\frac{\\log c}{\\log a} = \\log_a c $$ \uc774\ucc98\ub7fc \ubc11\uc758 \ubcc0\ud658\uc740 \ubcf5\uc7a1\ud55c \ub85c\uadf8 \uc2dd\uc744 \uac04\ub2e8\ud788 \uc57d\ubd84\ud558\uac70\ub098 \ud569\uce58\ub294 \uacfc\uc815\uc5d0\uc11c \uc218\ud559\uc801 \ud6a8\uc728\uc131\uc744 \uadf9\ub300\ud654\ud574 \uc90d\ub2c8\ub2e4.","\uc774\uc81c \uc608\uc81c\ub97c \ud1b5\ud574 \uc9c1\uc811 \uc801\uc6a9\ud574 \ubd05\uc2dc\ub2e4. \ubb38\uc81c: '$\\log_2 3 \\times \\log_3 4$\uc758 \uac12\uc744 \uad6c\ud558\uc2dc\uc624.' \uc774 \ubb38\uc81c\ub294 \ubc11\uc758 \ubcc0\ud658 \uacf5\uc2dd\uc744 \uc774\uc6a9\ud558\uba74 \uc544\uc8fc \uc27d\uac8c \ud574\uacb0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uac01 \ub85c\uadf8\ub97c \uc0c1\uc6a9\ub85c\uadf8(\ubc11\uc774 10\uc778 \ub85c\uadf8)\ub85c \ubcc0\ud658\ud558\uc5ec \uc2dd\uc744 \ub2e4\uc2dc \uc368\ubd05\ub2c8\ub2e4. $$ \\log_2 3 \\times \\log_3 4 = \\frac{\\log 3}{\\log 2} \\times \\frac{\\log 4}{\\log 3} $$","\uc704 \uc2dd\uc5d0\uc11c \ubd84\uc790\uc640 \ubd84\ubaa8\uc5d0 \uacf5\ud1b5\uc73c\ub85c \ub4e4\uc5b4\uc788\ub294 $\\log 3$\uc744 \uc57d\ubd84\ud569\ub2c8\ub2e4. \uadf8\ub7ec\uba74 \uc2dd\uc740 \ub2e4\uc74c\uacfc \uac19\uc774 \ub0a8\uac8c \ub429\ub2c8\ub2e4. $$ \\frac{\\log 4}{\\log 2} $$ \uc5ec\uae30\uc11c $4$\ub294 $2^2$\uc774\ubbc0\ub85c \ub85c\uadf8\uc758 \uc131\uc9c8\uc5d0 \uc758\ud574 $\\log 4 = \\log 2^2 = 2\\log 2$\ub85c \ubc14\uafc0 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub97c \ub300\uc785\ud558\uba74 \ucd5c\uc885 \uacb0\uacfc\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$ \\frac{2\\log 2}{\\log 2} = 2 $$ \ub530\ub77c\uc11c \uc8fc\uc5b4\uc9c4 \uc2dd\uc758 \uac12\uc740 $2$\uac00 \ub429\ub2c8\ub2e4."],ai0),u8,B.o)],ai2),u8,B.o)],ai3),s3,s3,s3,"concept_\ubc11\uc758\ubcc0\ud658",0,"","\ub300\uc218 > \ub85c\uadf8 > \ub85c\uadf8\uc758\uc131\uc9c8 > \ubc11\uc758\ubcc0\ud658",b0,u8,s3)
b1=A.a(["\ubbf8\uc801\ubd84\u2160","\uc18d\ub3c4\uc640\uac00\uc18d\ub3c4","\uc704\uce58\ud568\uc218"],ai0)
b1=A.av(s2,A.a([A.au(A.a(["\ubbf8\uc801\ubd84\u2160 > \uc18d\ub3c4\uc640\uac00\uc18d\ub3c4 > \uc704\uce58\ud568\uc218 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.q,A.a(["\uc218\uc9c1\uc120 \uc704\ub97c \uc6c0\uc9c1\uc774\ub294 \uc810 $P$\uc758 \uc2dc\uac01 $t$\uc5d0\uc11c\uc758 \uc704\uce58\ub97c $x(t)$\ub77c\uace0 \ud560 \ub54c, \uc774 \ud568\uc218 $x(t)$\ub97c \uc704\uce58\ud568\uc218\ub77c\uace0 \ud569\ub2c8\ub2e4. \uc704\uce58\ud568\uc218\ub294 \uc2dc\uac04\uc774 \ud750\ub984\uc5d0 \ub530\ub77c \uc810 $P$\uac00 \uc218\uc9c1\uc120 \uc704\uc758 \uc5b4\ub290 \uc9c0\uc810\uc5d0 \uc788\ub294\uc9c0\ub97c \ub098\ud0c0\ub0b4\uba70, \ubbf8\ubd84\uacfc \uc801\ubd84\uc758 \uad00\uacc4\ub97c \uc774\ud574\ud558\ub294 \ub370 \ub9e4\uc6b0 \uc911\uc694\ud55c \uae30\ucd08\uac00 \ub429\ub2c8\ub2e4. \uc810 $P$\uc758 \uc704\uce58\uac00 \uc2dc\uac01 $t$\uc5d0 \ub300\ud55c \ud568\uc218\ub85c \uc8fc\uc5b4\uc9c0\uba74, \uc6b0\ub9ac\ub294 \uadf8 \uc810\uc774 \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \uc5bc\ub9c8\ub098 \ube60\ub974\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c \uac00\uc18d\ub418\ub294\uc9c0\ub97c \uc218\ud559\uc801\uc73c\ub85c \ubd84\uc11d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc704\uce58\ud568\uc218 $x(t)$\ub97c \uc2dc\uac01 $t$\uc5d0 \ub300\ud558\uc5ec \ubbf8\ubd84\ud558\uba74 \uc810 $P$\uc758 \uc18d\ub3c4 $v(t)$\ub97c \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc989, \uc18d\ub3c4\ub294 \uc704\uce58\uc758 \ubcc0\ud654\uc728\uc744 \uc758\ubbf8\ud558\uba70 \uacf5\uc2dd\uc740 $$v(t) = \\frac{dx}{dt} = x'(t)$$\uc640 \uac19\uc2b5\ub2c8\ub2e4. \ub610\ud55c, \uc18d\ub3c4\ud568\uc218 $v(t)$\ub97c \ub2e4\uc2dc \ud55c\ubc88 \ubbf8\ubd84\ud558\uba74 \uac00\uc18d\ub3c4 $a(t)$\uac00 \ub418\ub294\ub370, \uc774\ub294 $$a(t) = \\frac{dv}{dt} = v'(t) = x''(t)$$\ub85c \ud45c\ud604\ub429\ub2c8\ub2e4. \ubc18\ub300\ub85c \uc18d\ub3c4\ud568\uc218\ub97c \uc801\ubd84\ud558\uba74 \uc704\uce58\uc758 \ubcc0\ud654\ub7c9\uc744 \uad6c\ud560 \uc218 \uc788\uc73c\uba70, \uc2dc\uac01 $t=a$\uc5d0\uc11c $t=b$\uae4c\uc9c0\uc758 \uc704\uce58 \ubcc0\ud654\ub7c9\uc740 $x(b) - x(a) = \\int_{a}^{b} v(t) dt$\ub77c\ub294 \uad00\uacc4\uac00 \uc131\ub9bd\ud569\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \uc704\uce58\ud568\uc218\ub97c \ub2e4\ub8e8\uc5b4 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uc218\uc9c1\uc120 \uc704\ub97c \uc6c0\uc9c1\uc774\ub294 \uc810 $P$\uc758 \uc2dc\uac01 $t$\uc5d0\uc11c\uc758 \uc704\uce58\ud568\uc218\uac00 $x(t) = t^3 - 6t^2 + 9t$\ub85c \uc8fc\uc5b4\uc84c\ub2e4\uace0 \uac00\uc815\ud569\uc2dc\ub2e4. \uc774\ub54c \uc2dc\uac01 $t=2$\uc5d0\uc11c\uc758 \uc810 $P$\uc758 \uc18d\ub3c4\uc640 \uac00\uc18d\ub3c4\ub97c \uad6c\ud558\ub294 \uacfc\uc815\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uc18d\ub3c4 $v(t)$\ub97c \uad6c\ud558\uae30 \uc704\ud574 \uc704\uce58\ud568\uc218\ub97c \ubbf8\ubd84\ud558\uba74 $$v(t) = x'(t) = 3t^2 - 12t + 9$$\uac00 \ub429\ub2c8\ub2e4.","\ub2e4\uc74c\uc73c\ub85c \uac00\uc18d\ub3c4 $a(t)$\ub97c \uad6c\ud558\uae30 \uc704\ud574 \uc18d\ub3c4\ud568\uc218\ub97c \ud55c \ubc88 \ub354 \ubbf8\ubd84\ud569\ub2c8\ub2e4. \uadf8\ub7ec\uba74 $$a(t) = v'(t) = 6t - 12$$\ub77c\ub294 \uc2dd\uc744 \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\uc81c \ubb38\uc81c\uc5d0\uc11c \uc694\uad6c\ud55c \uc2dc\uac01 $t=2$\ub97c \uac01\uac01\uc758 \uc2dd\uc5d0 \ub300\uc785\ud558\uc5ec \uac12\uc744 \uacc4\uc0b0\ud569\ub2c8\ub2e4. \uc18d\ub3c4\ub294 $$v(2) = 3(2)^2 - 12(2) + 9 = 12 - 24 + 9 = -3$$\uc774\uace0, \uac00\uc18d\ub3c4\ub294 $$a(2) = 6(2) - 12 = 0$$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc2dc\uac01 $t=2$\uc77c \ub54c \uc810 $P$\ub294 \uc74c\uc758 \ubc29\ud5a5\uc73c\ub85c \uc18d\ub825 3\ub9cc\ud07c \uc6c0\uc9c1\uc774\uace0 \uc788\uc73c\uba70, \uac00\uc18d\ub3c4\ub294 0\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),u9,B.o)],ai2),u9,B.o)],ai3),s3,s3,s3,"concept_\uc704\uce58\ud568\uc218",0,"","\ubbf8\uc801\ubd84\u2160 > \uc18d\ub3c4\uc640\uac00\uc18d\ub3c4 > \uc704\uce58\ud568\uc218",b1,u9,s3)
b2=A.a(["\uacf5\ud1b5\uc218\ud5591","\uacbd\uc6b0\uc758\uc218","\uc21c\uc5f4","\ud329\ud1a0\ub9ac\uc5bc"],ai0)
b2=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5591 > \uacbd\uc6b0\uc758\uc218 > \uc21c\uc5f4 > \ud329\ud1a0\ub9ac\uc5bc \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.q,A.a(["\ud329\ud1a0\ub9ac\uc5bc(factorial)\uc740 \uc11c\ub85c \ub2e4\ub978 $n$\uac1c\uc758 \ubb3c\uac74\uc744 \uc77c\ub82c\ub85c \ub098\uc5f4\ud558\ub294 \ubc29\ubc95\uc758 \uc218\ub97c \ub098\ud0c0\ub0b4\ub294 \uc218\ud559\uc801 \uac1c\ub150\uc785\ub2c8\ub2e4. \uae30\ud638\ub85c\ub294 $n!$\uc774\ub77c\uace0 \uc4f0\uba70, '$n$ \ud329\ud1a0\ub9ac\uc5bc' \ub610\ub294 '$n$ \uacc4\uc2b9'\uc774\ub77c\uace0 \uc77d\uc2b5\ub2c8\ub2e4. \uc774\ub294 $n$\ubd80\ud130 \uc2dc\uc791\ud558\uc5ec 1\uc529 \uc904\uc5ec\uac00\uba70 1\uae4c\uc9c0\uc758 \ubaa8\ub4e0 \uc790\uc5f0\uc218\ub97c \uacf1\ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc989, $n$\uac1c\uc758 \uc790\ub9ac\uc5d0 \uccab \ubc88\uc9f8 \uc790\ub9ac\uc5d0 \uc62c \uc218 \uc788\ub294 \uacbd\uc6b0\uc758 \uc218\uac00 $n$\uac00\uc9c0, \ub450 \ubc88\uc9f8 \uc790\ub9ac\uc5d0 \uc62c \uc218 \uc788\ub294 \uacbd\uc6b0\uc758 \uc218\uac00 $(n-1)$\uac00\uc9c0\uac00 \ub418\ub294 \uc2dd\uc73c\ub85c \ub9c8\uc9c0\ub9c9 \uc790\ub9ac\uae4c\uc9c0 \uacf1\ud574 \ub098\uac00\ub294 \uc6d0\ub9ac\uc785\ub2c8\ub2e4.","\ud329\ud1a0\ub9ac\uc5bc\uc758 \ud575\uc2ec \uacf5\uc2dd\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uc790\uc5f0\uc218 $n$\uc5d0 \ub300\ud558\uc5ec $n! = n \\times (n-1) \\times (n-2) \\times \\cdots \\times 2 \\times 1$\ub85c \uc815\uc758\ud569\ub2c8\ub2e4. \ub610\ud55c, \uc218\ud559\uc801 \ud3b8\uc758\ub97c \uc704\ud574 $0! = 1$\ub85c \uc57d\uc18d\ud569\ub2c8\ub2e4. \uc774\ub294 \uc544\ubb34\uac83\ub3c4 \uc120\ud0dd\ud558\uc9c0 \uc54a\ub294 \uacbd\uc6b0\uc758 \uc218\ub97c 1\uac00\uc9c0\ub85c \ubcf4\ub294 \uc870\ud569\ub860\uc801 \uad00\uc810\uacfc, $n! = n \\times (n-1)!$\uc774\ub77c\ub294 \uc810\ud654\uc2dd \uad00\uacc4\ub97c \uc720\uc9c0\ud558\uae30 \uc704\ud55c \uc57d\uc18d\uc785\ub2c8\ub2e4. \uc774 \uacf5\uc2dd\uc740 \uc21c\uc5f4\uc758 \uc218\ub97c \uacc4\uc0b0\ud560 \ub54c \ub9e4\uc6b0 \uc720\uc6a9\ud558\uac8c \uc0ac\uc6a9\ub429\ub2c8\ub2e4.","\ud329\ud1a0\ub9ac\uc5bc\uc758 \uc131\uc9c8 \uc911 \uac00\uc7a5 \uc911\uc694\ud55c \uac83\uc740 \ud070 \ud329\ud1a0\ub9ac\uc5bc\uc744 \uc791\uc740 \ud329\ud1a0\ub9ac\uc5bc\ub85c \ub098\ub204\uc5b4 \uac04\ub2e8\ud788 \ud45c\ud604\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, $n! = n \\times (n-1)!$\uacfc \uac19\uc774 \ud45c\ud604\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc131\uc9c8\uc744 \uc774\uc6a9\ud558\uba74 \ubcf5\uc7a1\ud55c \ubd84\uc218 \ud615\ud0dc\uc758 \uc21c\uc5f4 \uacc4\uc0b0\uc744 \ud6e8\uc52c \ube60\ub974\uace0 \uc815\ud655\ud558\uac8c \uc218\ud589\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud329\ud1a0\ub9ac\uc5bc\uc740 \uc22b\uc790\uac00 \ucee4\uc9c8\uc218\ub85d \uac12\uc774 \ub9e4\uc6b0 \ube60\ub974\uac8c \uc99d\uac00\ud558\ub294 \ud2b9\uc9d5\uc774 \uc788\uc5b4, \uacbd\uc6b0\uc758 \uc218\ub97c \ub2e4\ub8f0 \ub54c \ud544\uc218\uc801\uc778 \ub3c4\uad6c\uc785\ub2c8\ub2e4.","\uc608\uc81c: 5\uba85\uc758 \ud559\uc0dd\uc774 \uc77c\ub82c\ub85c \uc11c\uc11c \uc0ac\uc9c4\uc744 \ucc0d\ub294 \ubc29\ubc95\uc758 \uc218\ub97c \uad6c\ud574\ubcf4\uc138\uc694. \uc774 \ubb38\uc81c\ub294 \uc11c\ub85c \ub2e4\ub978 5\uac1c\ub97c \uc77c\ub82c\ub85c \ub098\uc5f4\ud558\ub294 \uc21c\uc5f4\uc758 \ubb38\uc81c\uc774\ubbc0\ub85c \ud329\ud1a0\ub9ac\uc5bc\uc744 \uc0ac\uc6a9\ud558\uc5ec \ud574\uacb0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uccab \ubc88\uc9f8 \uc790\ub9ac\uc5d0 5\uba85, \ub450 \ubc88\uc9f8 \uc790\ub9ac\uc5d0 4\uba85, \uc138 \ubc88\uc9f8 \uc790\ub9ac\uc5d0 3\uba85, \ub124 \ubc88\uc9f8 \uc790\ub9ac\uc5d0 2\uba85, \ub9c8\uc9c0\ub9c9 \uc790\ub9ac\uc5d0 1\uba85\uc774 \uc11c\ub294 \uacbd\uc6b0\uc758 \uc218\ub97c \ubaa8\ub450 \uacf1\ud558\uba74 \ub429\ub2c8\ub2e4.","\ub2e8\uacc4\ubcc4 \ud480\uc774: 5\uba85\uc758 \ud559\uc0dd\uc744 \uc77c\ub82c\ub85c \uc138\uc6b0\ub294 \uacbd\uc6b0\uc758 \uc218\ub294 $5!$\uc785\ub2c8\ub2e4. \uc774\ub97c \uacf5\uc2dd\uc5d0 \ub300\uc785\ud558\uba74 $5! = 5 \\times 4 \\times 3 \\times 2 \\times 1$\uc774 \ub429\ub2c8\ub2e4. \uacc4\uc0b0 \uacfc\uc815\uc744 \ucc28\ub840\ub300\ub85c \uc218\ud589\ud558\uba74 $5 \\times 4 = 20$, $20 \\times 3 = 60$, $60 \\times 2 = 120$, $120 \\times 1 = 120$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c 5\uba85\uc758 \ud559\uc0dd\uc744 \uc77c\ub82c\ub85c \uc138\uc6b0\ub294 \ubc29\ubc95\uc740 \ucd1d 120\uac00\uc9c0\uc785\ub2c8\ub2e4."],ai0),v0,B.o)],ai2),v0,B.o)],ai3),s3,s3,s3,"concept_\ud329\ud1a0\ub9ac\uc5bc",0,"","\uacf5\ud1b5\uc218\ud5591 > \uacbd\uc6b0\uc758\uc218 > \uc21c\uc5f4 > \ud329\ud1a0\ub9ac\uc5bc",b2,v0,s3)
b3=A.a(["\uacf5\ud1b5\uc218\ud5592","\ud568\uc218","\ud568\uc218\uc758\uc815\uc758","\uce58\uc5ed"],ai0)
b3=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5592 > \ud568\uc218 > \ud568\uc218\uc758\uc815\uc758 > \uce58\uc5ed \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.q,A.a(['[   "\ud568\uc218 $f: X \\\\to Y$\uc5d0\uc11c \uc815\uc758\uc5ed $X$\uc758 \uac01 \uc6d0\uc18c $x$\uc5d0 \ub300\uc751\ud558\ub294 \uacf5\uc5ed $Y$\uc758 \uc6d0\uc18c \uc804\uccb4\uc758 \uc9d1\ud569\uc744 \'\uce58\uc5ed\'\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \uc27d\uac8c \ub9d0\ud574, \ud568\uc218\ub97c \ud1b5\ud574 \uc2e4\uc81c\ub85c \'\uc120\ud0dd\ubc1b\uc740\' \uacf5\uc5ed\uc758 \uc6d0\uc18c\ub4e4\ub9cc\uc744 \ubaa8\uc544\ub193\uc740 \uc9d1\ud569\uc785\ub2c8\ub2e4. \uacf5\uc5ed\uc740 \ud568\uc218\uac00 \ub3c4\ucc29\ud560 \uc218 \uc788\ub294 \ud6c4\ubcf4\uc9c0 \uc804\uccb4\ub97c \uc758\ubbf8\ud558\uc9c0\ub9cc, \uce58\uc5ed\uc740 \uadf8\uc911\uc5d0\uc11c \uc2e4\uc81c\ub85c \ud654\uc0b4\ud45c\ub97c \ubc1b\uc740 \uac12\ub4e4\ub9cc\uc744 \uc758\ubbf8\ud558\ubbc0\ub85c \uce58\uc5ed\uc740 \ud56d\uc0c1 \uacf5\uc5ed\uc758 \ubd80\ubd84\uc9d1\ud569\uc774 \ub429\ub2c8\ub2e4.",   "\uce58\uc5ed\uc744 \uc218\ud559\uc801 \uae30\ud638\ub85c \ub098\ud0c0\ub0b4\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uc815\uc758\uc5ed $X$\uc758 \uc784\uc758\uc758 \uc6d0\uc18c $x$\uc5d0 \ub300\ud558\uc5ec $f(x)$\uc758 \uac12\ub4e4\uc744 \ubaa8\ub450 \ubaa8\uc740 \uc9d1\ud569\uc744 \uce58\uc5ed\uc774\ub77c \ud558\uba70, \ubcf4\ud1b5 $f(X)$ \ub610\ub294 $\\{f(x) | x \\\\in X\\}$\ub85c \ud45c\ud604\ud569\ub2c8\ub2e4. \uacf5\uc2dd\uc73c\ub85c \uc815\ub9ac\ud558\uba74 $$f(X) = \\\\{ y \\\\in Y \\\\mid y = f(x) \\\\text{\ub97c \ub9cc\uc871\ud558\ub294 } x \\\\in X \\\\text{\uac00 \uc874\uc7ac\ud55c\ub2e4} \\\\}$$\uc640 \uac19\uc774 \ub098\ud0c0\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \uc815\uc758\ub97c \ud1b5\ud574 \uc6b0\ub9ac\ub294 \ud568\uc218\uac00 \uc8fc\uc5b4\uc84c\uc744 \ub54c, \uc815\uc758\uc5ed\uc758 \ubaa8\ub4e0 \uc6d0\uc18c\ub97c \ub300\uc785\ud558\uc5ec \ub098\uc624\ub294 \uacb0\uacfc\uac12\ub4e4\uc758 \ubc94\uc704\ub97c \ucc3e\uc544\ub0c4\uc73c\ub85c\uc368 \uce58\uc5ed\uc744 \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.",   "\uc608\ub97c \ub4e4\uc5b4, \uc815\uc758\uc5ed\uc774 $X = \\\\{-1, 0, 1\\\\}$\uc774\uace0 \ud568\uc218\uac00 $f(x) = x^2$\uc73c\ub85c \uc815\uc758\ub41c \uacbd\uc6b0\ub97c \uc0dd\uac01\ud574 \ubd05\uc2dc\ub2e4. \uac01 \uc6d0\uc18c\ub97c \ub300\uc785\ud558\uba74 $f(-1) = (-1)^2 = 1$, $f(0) = 0^2 = 0$, $f(1) = 1^2 = 1$\uc774 \ub429\ub2c8\ub2e4. \uc774\ub54c \uacb0\uacfc\uac12\uc740 $0$\uacfc $1$\uc774\ubbc0\ub85c, \uc774 \ud568\uc218\uc758 \uce58\uc5ed\uc740 $\\{0, 1\\}$\uc774 \ub429\ub2c8\ub2e4. \uacf5\uc5ed\uc774 \ub9cc\uc57d \uc2e4\uc218 \uc804\uccb4\uc758 \uc9d1\ud569\uc774\uc5c8\ub2e4\uba74, \uce58\uc5ed\uc740 \uacf5\uc5ed\uc758 \uc77c\ubd80\ubd84\uc778 $\\{0, 1\\}$\ub9cc \ud574\ub2f9\ud558\uac8c \ub418\ub294 \uac83\uc785\ub2c8\ub2e4.",   "\uc870\uae08 \ub354 \ubcf5\uc7a1\ud55c \uc608\uc81c\ub85c, \uc815\uc758\uc5ed\uc774 $\\{x \\\\mid -2 \\\\le x \\\\le 3\\}$\uc778 \ud568\uc218 $f(x) = 2x - 1$\uc758 \uce58\uc5ed\uc744 \uad6c\ud558\ub294 \uacfc\uc815\uc744 \ub2e8\uacc4\ubcc4\ub85c \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uccab\uc9f8, \uc8fc\uc5b4\uc9c4 \ud568\uc218\uc758 \uc815\uc758\uc5ed \uc591 \ub05d\uac12\uc744 \ub300\uc785\ud558\uc5ec \ud568\uc22b\uac12\uc744 \uad6c\ud569\ub2c8\ub2e4. $x = -2$\uc77c \ub54c $f(-2) = 2(-2) - 1 = -5$\uc774\uace0, $x = 3$\uc77c \ub54c $f(3) = 2(3) - 1 = 5$\uc785\ub2c8\ub2e4.",   "\ub458\uc9f8, \ud568\uc218 $f(x) = 2x - 1$\uc740 \uae30\uc6b8\uae30\uac00 \uc591\uc218\uc778 \uc9c1\uc120\uc774\ubbc0\ub85c $x$\uac12\uc774 \ucee4\uc9c8\uc218\ub85d $f(x)$\uac12\ub3c4 \ucee4\uc9d1\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc815\uc758\uc5ed\uc758 \ubc94\uc704\uac00 $-2$\uc5d0\uc11c $3$\uae4c\uc9c0\uc77c \ub54c, \ud568\uc22b\uac12\uc740 $-5$\uc5d0\uc11c $5$\uae4c\uc9c0 \uc5f0\uc18d\uc801\uc73c\ub85c \ub098\ud0c0\ub098\uac8c \ub429\ub2c8\ub2e4. \uc774\ub97c \ubd80\ub4f1\uc2dd\uc73c\ub85c \ud45c\ud604\ud558\uba74 $-5 \\\\le f(x) \\\\le 5$\uac00 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc774 \ud568\uc218\uc758 \uce58\uc5ed\uc740 $\\{y \\\\mid -5 \\\\le y \\\\le 5\\}$\uac00 \ub429\ub2c8\ub2e4." ]'],ai0),"\uce58\uc5ed",B.o)],ai2),"\uce58\uc5ed",B.o)],ai3),s3,s3,s3,"concept_\uce58\uc5ed",0,"","\uacf5\ud1b5\uc218\ud5592 > \ud568\uc218 > \ud568\uc218\uc758\uc815\uc758 > \uce58\uc5ed",b3,"\uce58\uc5ed",s3)
b4=A.a(["\uacf5\ud1b5\uc218\ud5591","\ubcf5\uc18c\uc218","\ubcf5\uc18c\uc218\uc758\uc5f0\uc0b0"],ai0)
b4=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5591 > \ubcf5\uc18c\uc218 > \ubcf5\uc18c\uc218\uc758\uc5f0\uc0b0 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.q,A.a(["\ubcf5\uc18c\uc218\ub780 \uc2e4\uc218\uc640 \ud5c8\uc218\ub2e8\uc704 $i$\ub97c \uc774\uc6a9\ud558\uc5ec $a+bi$ (\ub2e8, $a, b$\ub294 \uc2e4\uc218)\uc758 \uaf34\ub85c \ub098\ud0c0\ub0b4\ub294 \uc218\uc785\ub2c8\ub2e4. \uc5ec\uae30\uc11c $i$\ub294 \uc81c\uacf1\ud558\uc5ec $-1$\uc774 \ub418\ub294 \uc218, \uc989 $i^2 = -1$\uc744 \ub9cc\uc871\ud558\ub294 \ub2e8\uc704\uc785\ub2c8\ub2e4. \ubcf5\uc18c\uc218\uc758 \ub367\uc148\uacfc \ube84\uc148\uc740 \ub2e4\ud56d\uc2dd\uc758 \uacc4\uc0b0\uacfc \ub9e4\uc6b0 \uc720\uc0ac\ud569\ub2c8\ub2e4. \uc2e4\uc218 \ubd80\ubd84\uc740 \uc2e4\uc218 \ubd80\ubd84\ub07c\ub9ac, \ud5c8\uc218 \ubd80\ubd84\uc740 \ud5c8\uc218 \ubd80\ubd84\ub07c\ub9ac \ubaa8\uc544\uc11c \uacc4\uc0b0\ud558\uba74 \ub429\ub2c8\ub2e4. \uc989, \ub450 \ubcf5\uc18c\uc218 $z_1 = a+bi$, $z_2 = c+di$\uc5d0 \ub300\ud558\uc5ec \ub367\uc148\uacfc \ube84\uc148\uc740 \ub2e4\uc74c\uacfc \uac19\uc774 \uc815\uc758\ud569\ub2c8\ub2e4.","$$z_1 + z_2 = (a+c) + (b+d)i$$ $$z_1 - z_2 = (a-c) + (b-d)i$$ \ubcf5\uc18c\uc218\uc758 \uacf1\uc148\uc740 \ubd84\ubc30\ubc95\uce59\uc744 \uc774\uc6a9\ud558\uc5ec \uc804\uac1c\ud55c \ub4a4, $i^2 = -1$\uc784\uc744 \uc774\uc6a9\ud558\uc5ec \uc2e4\uc218 \ubd80\ubd84\uacfc \ud5c8\uc218 \ubd80\ubd84\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4. \ub098\ub217\uc148\uc740 \ubd84\ubaa8\uc758 \ucf24\ub808\ubcf5\uc18c\uc218\ub97c \ubd84\ubaa8\uc640 \ubd84\uc790\uc5d0 \uac01\uac01 \uacf1\ud558\uc5ec \ubd84\ubaa8\ub97c \uc2e4\uc218\ud654\ud55c \ub4a4 \uacc4\uc0b0\ud569\ub2c8\ub2e4. $z = a+bi$\uc77c \ub54c, \uadf8 \ucf24\ub808\ubcf5\uc18c\uc218\ub294 $\\bar{z} = a-bi$\uc774\uba70, $z\\bar{z} = a^2+b^2$\uc774\ub77c\ub294 \uc131\uc9c8\uc744 \uc774\uc6a9\ud558\uba74 \ub098\ub217\uc148\uc744 \uc27d\uac8c \uc218\ud589\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \ubcf5\uc18c\uc218\uc758 \uc5f0\uc0b0\uc744 \uc775\ud600\ubd05\uc2dc\ub2e4. \uccab \ubc88\uc9f8 \uc608\uc81c\ub85c \ub450 \ubcf5\uc18c\uc218 $z_1 = 3+2i$, $z_2 = 1-4i$\uac00 \uc8fc\uc5b4\uc84c\uc744 \ub54c, $z_1 + z_2$\uc640 $z_1 - z_2$\ub97c \uacc4\uc0b0\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ub367\uc148\uc740 \uc2e4\uc218\ubd80\ub07c\ub9ac \ub354\ud558\uace0 \ud5c8\uc218\ubd80\ub07c\ub9ac \ub354\ud569\ub2c8\ub2e4. $z_1 + z_2 = (3+1) + (2-4)i = 4-2i$\uac00 \ub429\ub2c8\ub2e4. \ube84\uc148\uc740 $z_1 - z_2 = (3-1) + (2-(-4))i = 2+6i$\uac00 \ub429\ub2c8\ub2e4.","\ub450 \ubc88\uc9f8 \uc608\uc81c\ub85c \ubcf5\uc18c\uc218\uc758 \uacf1\uc148\uc744 \uc0b4\ud3b4\ubd05\uc2dc\ub2e4. $(2+i)(3-2i)$\ub97c \uacc4\uc0b0\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ubd84\ubc30\ubc95\uce59\uc744 \uc801\uc6a9\ud558\uba74 $(2+i)(3-2i) = 2 \\cdot 3 + 2 \\cdot (-2i) + i \\cdot 3 + i \\cdot (-2i) = 6 - 4i + 3i - 2i^2$\uc785\ub2c8\ub2e4. \uc5ec\uae30\uc11c $i^2 = -1$\uc774\ubbc0\ub85c $-2i^2 = -2(-1) = 2$\uac00 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc2dd\uc744 \uc815\ub9ac\ud558\uba74 $(6+2) + (-4+3)i = 8-i$\ub77c\ub294 \uacb0\uacfc\ub97c \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub9c8\uc9c0\ub9c9\uc73c\ub85c \ubcf5\uc18c\uc218\uc758 \ub098\ub217\uc148 \uc608\uc81c\uc785\ub2c8\ub2e4. $\\frac{1+i}{2-i}$\ub97c \uacc4\uc0b0\ud558\ub824\uba74 \ubd84\ubaa8\uc758 \ucf24\ub808\ubcf5\uc18c\uc218\uc778 $2+i$\ub97c \ubd84\ubaa8\uc640 \ubd84\uc790\uc5d0 \uacf1\ud569\ub2c8\ub2e4. \uc2dd\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$\\frac{1+i}{2-i} = \\frac{(1+i)(2+i)}{(2-i)(2+i)} = \\frac{2+i+2i+i^2}{2^2 - i^2}$$ \ubd84\ubaa8\ub294 $4 - (-1) = 5$\uac00 \ub418\uace0, \ubd84\uc790\ub294 $2+3i-1 = 1+3i$\uac00 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \ucd5c\uc885 \uacb0\uacfc\ub294 $\\frac{1}{5} + \\frac{3}{5}i$\uc785\ub2c8\ub2e4."],ai0),v1,B.o)],ai2),v1,B.o)],ai3),s3,s3,s3,"concept_\ubcf5\uc18c\uc218\uc758\uc5f0\uc0b0",0,"","\uacf5\ud1b5\uc218\ud5591 > \ubcf5\uc18c\uc218 > \ubcf5\uc18c\uc218\uc758\uc5f0\uc0b0",b4,v1,s3)
b5=A.a(["\ubbf8\uc801\ubd84\u2160","\ud568\uc218\uc758\uadf9\ud55c","\uadf9\ud55c\uc758\uc815\uc758","\uc88c\uadf9\ud55c"],ai0)
b5=A.av(s2,A.a([A.au(A.a(["\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uadf9\ud55c > \uadf9\ud55c\uc758\uc815\uc758 > \uc88c\uadf9\ud55c \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.q,A.a(["\ud568\uc218\uc758 \uadf9\ud55c\uc5d0\uc11c '\uc88c\uadf9\ud55c'\uc774\ub780, \ubcc0\uc218 $x$\uac00 \uc5b4\ub5a4 \uac12 $a$\ubcf4\ub2e4 \uc791\uc740 \uac12\uc744 \uac00\uc9c0\uba74\uc11c $a$\uc5d0 \ud55c\uc5c6\uc774 \uac00\uae4c\uc6cc\uc9c8 \ub54c, \ud568\uc218 $f(x)$\uc758 \uac12\uc774 \ub3c4\ub2ec\ud558\ub294 \ubaa9\ud45c \uc9c0\uc810\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc774\ub97c \uae30\ud638\ub85c\ub294 $x$\uac00 $a$\uc758 \uc67c\ucabd\uc5d0\uc11c \ub2e4\uac00\uc628\ub2e4\ub294 \ub73b\uc758 $x \\to a^-$\ub97c \uc0ac\uc6a9\ud558\uc5ec \ub2e4\uc74c\uacfc \uac19\uc774 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \uc989, $x$\uac00 $a$\ubcf4\ub2e4 \uc791\uc740 \ubc94\uc704\uc5d0\uc11c $a$\ub85c \uc811\uadfc\ud560 \ub54c $f(x)$\uac00 \uc77c\uc815\ud55c \uac12 $L$\uc5d0 \uc218\ub834\ud55c\ub2e4\uba74, \uc774\ub97c $L$\uc744 $x=a$\uc5d0\uc11c\uc758 \uc88c\uadf9\ud55c\uc774\ub77c \ud558\uace0 $\\lim_{x \\to a^-} f(x) = L$\uc774\ub77c\uace0 \uc501\ub2c8\ub2e4.","\uc88c\uadf9\ud55c\uc744 \uc774\ud574\ud560 \ub54c \uc911\uc694\ud55c \uc810\uc740 $x$\uac00 $a$\uc5d0 \ub3c4\ub2ec\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, $a$\ubcf4\ub2e4 \uc791\uc740 \ucabd\uc5d0\uc11c \uc544\uc8fc \uac00\uae4c\uc6b4 \uac12\ub4e4\uc744 \ub300\uc785\ud588\uc744 \ub54c \ud568\uc218\uac00 \uc5b4\ub5a4 \ub192\uc774\ub85c \ud5a5\ud558\ub294\uc9c0\ub97c \uad00\ucc30\ud558\ub294 \uac83\uc785\ub2c8\ub2e4. \ub9cc\uc57d \ud568\uc218\uac00 $x=a$\ub97c \uae30\uc900\uc73c\ub85c \uc67c\ucabd\uacfc \uc624\ub978\ucabd\uc5d0\uc11c \uc11c\ub85c \ub2e4\ub978 \uac12\uc73c\ub85c \ud5a5\ud55c\ub2e4\uba74, \uc88c\uadf9\ud55c\uacfc \uc6b0\uadf9\ud55c\uc774 \ub2e4\ub974\ub2e4\uace0 \ub9d0\ud569\ub2c8\ub2e4. \ud568\uc218\uc758 \uadf9\ud55c\uac12\uc774 \uc874\uc7ac\ud558\uae30 \uc704\ud574\uc11c\ub294 \uc88c\uadf9\ud55c\uacfc \uc6b0\uadf9\ud55c\uc774 \ubaa8\ub450 \uc874\uc7ac\ud558\uace0 \uadf8 \ub450 \uac12\uc774 \uc11c\ub85c \uac19\uc544\uc57c \ud55c\ub2e4\ub294 \uc810\uc744 \ubc18\ub4dc\uc2dc \uae30\uc5b5\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc608\ub97c \ub4e4\uc5b4, \ud568\uc218 $f(x) = \\begin{cases} x+1 & (x < 1) \\\\ 3 & (x \\ge 1) \\end{cases}$\uac00 \uc8fc\uc5b4\uc84c\uc744 \ub54c, $x=1$\uc5d0\uc11c\uc758 \uc88c\uadf9\ud55c\uc744 \uad6c\ud574\ubd05\uc2dc\ub2e4. \uc88c\uadf9\ud55c\uc740 $x$\uac00 1\ubcf4\ub2e4 \uc791\uc740 \ucabd\uc5d0\uc11c 1\ub85c \ub2e4\uac00\uac08 \ub54c\uc758 \uac12\uc774\ubbc0\ub85c, $x < 1$\uc77c \ub54c\uc758 \uc2dd\uc778 $f(x) = x+1$\uc744 \uc774\uc6a9\ud569\ub2c8\ub2e4. \uc774\ub54c $x$\uc5d0 1\uc744 \ub300\uc785\ud558\ub294 \uac83\ucc98\ub7fc \uc0dd\uac01\ud558\uba74 $\\lim_{x \\to 1^-} f(x) = \\lim_{x \\to 1^-} (x+1) = 1+1 = 2$\uac00 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc774 \ud568\uc218\uc758 $x=1$\uc5d0\uc11c\uc758 \uc88c\uadf9\ud55c\uc740 2\uc785\ub2c8\ub2e4.","\ub610 \ub2e4\ub978 \uc608\uc81c\ub85c, \uac00\uc6b0\uc2a4 \ud568\uc218 $f(x) = [x]$\uc758 $x=2$\uc5d0\uc11c\uc758 \uc88c\uadf9\ud55c\uc744 \uad6c\ud574\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uac00\uc6b0\uc2a4 \uae30\ud638 $[x]$\ub294 $x$\ubcf4\ub2e4 \ud06c\uc9c0 \uc54a\uc740 \ucd5c\ub300\uc758 \uc815\uc218\ub97c \uc758\ubbf8\ud569\ub2c8\ub2e4. $x$\uac00 2\ubcf4\ub2e4 \uc791\uc740 \ucabd\uc5d0\uc11c 2\ub85c \ub2e4\uac00\uac08 \ub54c, $x$\ub294 1.9, 1.99, 1.999\uc640 \uac19\uc740 \uac12\uc744 \uac00\uc9d1\ub2c8\ub2e4. \uc774 \uac12\ub4e4\uc5d0 \ub300\ud574 \uac00\uc6b0\uc2a4 \uae30\ud638\ub97c \uc50c\uc6b0\uba74 $[1.9] = 1, [1.99] = 1, [1.999] = 1$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c $x$\uac00 2\ubcf4\ub2e4 \uc791\uc740 \ucabd\uc5d0\uc11c \uc811\uadfc\ud560 \ub54c \ud568\uc218\uac12\uc740 \ud56d\uc0c1 1\uc744 \uc720\uc9c0\ud558\ubbc0\ub85c, $\\lim_{x \\to 2^-} [x] = 1$\uc774 \ub429\ub2c8\ub2e4.","\ub9c8\uc9c0\ub9c9\uc73c\ub85c \uadf8\ub798\ud504\uac00 \ub04a\uc5b4\uc838 \uc788\ub294 \ud568\uc218 $g(x)$\uc5d0\uc11c $x=0$\uc77c \ub54c\uc758 \uc88c\uadf9\ud55c\uc744 \ud655\uc778\ud574 \ubd05\uc2dc\ub2e4. \uadf8\ub798\ud504 \uc0c1\uc5d0\uc11c $x$\ucd95\uc758 \uc74c\uc218 \ubc29\ud5a5\uc5d0\uc11c 0\uc73c\ub85c \ub2e4\uac00\uac08 \ub54c, \ud568\uc218\uac00 $y=3$\uc774\ub77c\ub294 \ub192\uc774\ub97c \ud5a5\ud574 \uac00\uace0 \uc788\ub2e4\uba74 \uc88c\uadf9\ud55c\uc740 3\uc785\ub2c8\ub2e4. \ub9cc\uc57d $x=0$\uc77c \ub54c\uc758 \uc2e4\uc81c \ud568\uc22b\uac12\uc774 5\ub77c\uace0 \ud558\ub354\ub77c\ub3c4, \uc88c\uadf9\ud55c\uc740 '\ub2e4\uac00\uac00\ub294 \ubaa9\ud45c \uc9c0\uc810'\uc744 \uc758\ubbf8\ud558\ubbc0\ub85c \ud568\uc22b\uac12\uacfc\ub294 \ubb34\uad00\ud558\uac8c 3\uc774 \ub429\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc88c\uadf9\ud55c\uc740 \uadf8\ub798\ud504\uc758 \uc67c\ucabd \ub05d\uc5d0\uc11c\ubd80\ud130 0\uc744 \ud5a5\ud574 \uc190\uac00\ub77d\uc744 \ub530\ub77c\uac14\uc744 \ub54c \ub3c4\ucc29\ud558\ub294 $y$\uc88c\ud45c\ub97c \uc77d\ub294 \uac83\uacfc \uac19\uc2b5\ub2c8\ub2e4."],ai0),"\uc88c\uadf9\ud55c",B.o)],ai2),"\uc88c\uadf9\ud55c",B.o)],ai3),s3,s3,s3,"concept_\uc88c\uadf9\ud55c",0,"","\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uadf9\ud55c > \uadf9\ud55c\uc758\uc815\uc758 > \uc88c\uadf9\ud55c",b5,"\uc88c\uadf9\ud55c",s3)
b6=A.a(["\uacf5\ud1b5\uc218\ud5592","\uc88c\ud45c\ud3c9\uba74","\uc810\uacfc\uc9c1\uc120\uc0ac\uc774\uc758\uac70\ub9ac","\uac70\ub9ac\uacf5\uc2dd(\uc810\uc9c1\uc120)"],ai0)
b6=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc810\uacfc\uc9c1\uc120\uc0ac\uc774\uc758\uac70\ub9ac > \uac70\ub9ac\uacf5\uc2dd(\uc810\uc9c1\uc120) \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.q,A.a(["\uc88c\ud45c\ud3c9\uba74 \uc704\uc5d0\uc11c \ud55c \uc810 $P(x_1, y_1)$\uacfc \uc9c1\uc120 $ax + by + c = 0$ \uc0ac\uc774\uc758 \uac70\ub9ac\ub294 \uc810 $P$\uc5d0\uc11c \uc9c1\uc120\uc5d0 \ub0b4\ub9b0 \uc218\uc120\uc758 \ubc1c\uae4c\uc9c0\uc758 \uc120\ubd84 \uae38\uc774\ub97c \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc774 \uac70\ub9ac\ub294 \uc9c1\uc120 \uc704\uc758 \ubaa8\ub4e0 \uc810 \uc911\uc5d0\uc11c \uc810 $P$\uc640 \uac00\uc7a5 \uac00\uae4c\uc6b4 \uac70\ub9ac\ub97c \ub098\ud0c0\ub0b4\uba70, \uae30\ud558\ud559\uc801\uc73c\ub85c\ub294 \uc810\uacfc \uc9c1\uc120\uc774 \uc774\ub8e8\ub294 \ucd5c\ub2e8 \uac70\ub9ac\ub97c \ub73b\ud569\ub2c8\ub2e4. \uc774 \uac70\ub9ac\ub97c \uad6c\ud558\uae30 \uc704\ud574\uc11c\ub294 \uc9c1\uc120\uc758 \ubc29\uc815\uc2dd\uc774 \uc77c\ubc18\ud615\uc778 $ax + by + c = 0$ \uaf34\ub85c \uc815\ub9ac\ub418\uc5b4 \uc788\uc5b4\uc57c \ud569\ub2c8\ub2e4.","\uc810 $(x_1, y_1)$\uacfc \uc9c1\uc120 $ax + by + c = 0$ \uc0ac\uc774\uc758 \uac70\ub9ac $d$\ub97c \uad6c\ud558\ub294 \uacf5\uc2dd\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \ubd84\uc790\uc5d0\ub294 \uc810\uc758 \uc88c\ud45c\ub97c \uc9c1\uc120\uc758 \ubc29\uc815\uc2dd\uc5d0 \ub300\uc785\ud55c \uac12\uc758 \uc808\ub313\uac12\uc744 \ucde8\ud558\uace0, \ubd84\ubaa8\uc5d0\ub294 \uc9c1\uc120\uc758 $x$ \uacc4\uc218\uc640 $y$ \uacc4\uc218\uc758 \uc81c\uacf1\uc758 \ud569\uc5d0 \ub8e8\ud2b8\ub97c \uc50c\uc6b4 \uac12\uc744 \ubc30\uce58\ud569\ub2c8\ub2e4. \uacf5\uc2dd\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$d = \\frac{|ax_1 + by_1 + c|}{\\sqrt{a^2 + b^2}}$$ \uc774 \uacf5\uc2dd\uc740 \uc810\uacfc \uc9c1\uc120 \uc0ac\uc774\uc758 \uc704\uce58 \uad00\uacc4\ub97c \ud30c\uc545\ud558\uac70\ub098, \uc6d0\uacfc \uc9c1\uc120\uc774 \uc811\ud558\ub294 \uc870\uac74\uc744 \uad6c\ud560 \ub54c \ub9e4\uc6b0 \uc720\uc6a9\ud558\uac8c \uc0ac\uc6a9\ub429\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \uacf5\uc2dd\uc744 \uc801\uc6a9\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uc810 $P(2, 1)$\uacfc \uc9c1\uc120 $3x + 4y - 5 = 0$ \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uad6c\ud574 \ubd05\uc2dc\ub2e4. \uba3c\uc800 \uacf5\uc2dd\uc5d0 \ub300\uc785\ud558\uae30 \uc704\ud574 \uc810\uc758 \uc88c\ud45c $x_1 = 2, y_1 = 1$\uacfc \uc9c1\uc120\uc758 \uacc4\uc218 $a = 3, b = 4, c = -5$\ub97c \ud655\uc778\ud569\ub2c8\ub2e4. \uc774 \uac12\ub4e4\uc744 \uacf5\uc2dd\uc5d0 \uadf8\ub300\ub85c \ub300\uc785\ud558\uba74 \uacc4\uc0b0\uc744 \uc2dc\uc791\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub2e8\uacc4\ubcc4 \ud480\uc774\ub97c \uc9c4\ud589\ud558\uba74, \uba3c\uc800 \ubd84\uc790\uc5d0 \uc810 $(2, 1)$\uc744 \uc9c1\uc120\uc758 \uc2dd\uc5d0 \ub300\uc785\ud558\uc5ec $|3(2) + 4(1) - 5|$\ub97c \uacc4\uc0b0\ud569\ub2c8\ub2e4. \uc774\ub294 $|6 + 4 - 5| = |5| = 5$\uac00 \ub429\ub2c8\ub2e4. \ub2e4\uc74c\uc73c\ub85c \ubd84\ubaa8\uc5d0\ub294 $\\sqrt{3^2 + 4^2}$\uc744 \uacc4\uc0b0\ud569\ub2c8\ub2e4. $\\sqrt{9 + 16} = \\sqrt{25} = 5$\uac00 \ub418\ubbc0\ub85c, \ucd5c\uc885\uc801\uc73c\ub85c \uac70\ub9ac $d$\ub294 \ub2e4\uc74c\uacfc \uac19\uc774 \uacc4\uc0b0\ub429\ub2c8\ub2e4. $$d = \\frac{5}{5} = 1$$ \ub530\ub77c\uc11c \uc810 $(2, 1)$\uacfc \uc9c1\uc120 \uc0ac\uc774\uc758 \uac70\ub9ac\ub294 $1$\uc785\ub2c8\ub2e4."],ai0),v2,B.o)],ai2),v2,B.o)],ai3),s3,s3,s3,"concept_\uac70\ub9ac\uacf5\uc2dd(\uc810\uc9c1\uc120)",0,"","\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc810\uacfc\uc9c1\uc120\uc0ac\uc774\uc758\uac70\ub9ac > \uac70\ub9ac\uacf5\uc2dd(\uc810\uc9c1\uc120)",b6,v2,s3)
b7=A.a(["\ub300\uc218","\ub85c\uadf8","\ub85c\uadf8\uc758\uc131\uc9c8","\uc0c1\uc6a9\ub85c\uadf8"],ai0)
b7=A.av(s2,A.a([A.au(A.a(["\ub300\uc218 > \ub85c\uadf8 > \ub85c\uadf8\uc758\uc131\uc9c8 > \uc0c1\uc6a9\ub85c\uadf8 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.q,A.a(["\uc0c1\uc6a9\ub85c\uadf8\ub780 \ubc11\uc774 10\uc778 \ub85c\uadf8\ub97c \ub9d0\ud558\uba70, \uc218\ud559\uacfc \uacfc\ud559 \ubd84\uc57c\uc5d0\uc11c \ub9e4\uc6b0 \uc790\uc8fc \uc0ac\uc6a9\ub418\uae30 \ub54c\ubb38\uc5d0 \ubc11 10\uc744 \uc0dd\ub7b5\ud558\uc5ec \uac04\ub2e8\ud788 $\\log_{10} N$\uc744 $\\log N$\uacfc \uac19\uc774 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. 10\uc744 \ubc11\uc73c\ub85c \ud558\ub294 \uc774\uc720\ub294 \uc6b0\ub9ac\uac00 \uc77c\uc0c1\uc0dd\ud65c\uc5d0\uc11c \uc2ed\uc9c4\ubc95\uc744 \uc0ac\uc6a9\ud558\uae30 \ub54c\ubb38\uc778\ub370, \uc774\ub97c \ud1b5\ud574 \ud070 \uc218\ub098 \uc544\uc8fc \uc791\uc740 \uc218\ub97c \ub2e4\ub8f0 \ub54c \uc790\ub9bf\uc218\ub97c \uc27d\uac8c \ud30c\uc545\ud560 \uc218 \uc788\ub2e4\ub294 \uc7a5\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\uc0c1\uc6a9\ub85c\uadf8\uc758 \uac12\uc740 \uc77c\ubc18\uc801\uc73c\ub85c \uc815\uc218 \ubd80\ubd84\uacfc \uc18c\uc218 \ubd80\ubd84\uc73c\ub85c \ub098\ub269\ub2c8\ub2e4. \uc591\uc218 $N$\uc5d0 \ub300\ud558\uc5ec $\\log N = n + \\alpha$ (\ub2e8, $n$\uc740 \uc815\uc218, $0 \\le \\alpha < 1$)\ub77c\uace0 \ud560 \ub54c, \uc815\uc218 \ubd80\ubd84 $n$\uc740 \uc218\uc758 \uc790\ub9bf\uc218\ub098 \uc18c\uc218\uc810 \uc544\ub798 \uccab \ubc88\uc9f8\ub85c 0\uc774 \uc544\ub2cc \uc22b\uc790\uac00 \ub098\ud0c0\ub098\ub294 \uc704\uce58\ub97c \uacb0\uc815\ud558\uba70, \uc18c\uc218 \ubd80\ubd84 $\\alpha$\ub294 \uc218\uc758 \uc22b\uc790 \ubc30\uc5f4\uc744 \uacb0\uc815\ud569\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc131\uc9c8 \ub355\ubd84\uc5d0 \uc0c1\uc6a9\ub85c\uadf8\ud45c\ub97c \uc774\uc6a9\ud558\uba74 \ubcf5\uc7a1\ud55c \uc218\uc758 \uacc4\uc0b0\uc744 \ud6e8\uc52c \uc218\uc6d4\ud558\uac8c \ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc608\ub97c \ub4e4\uc5b4, $\\log 10 = 1$, $\\log 100 = 2$, $\\log 1000 = 3$\uacfc \uac19\uc774 10\uc758 \uac70\ub4ed\uc81c\uacf1 \ud615\ud0dc\ub294 \uc0c1\uc6a9\ub85c\uadf8\ub97c \ucde8\ud588\uc744 \ub54c \uc815\uc218\ub85c \uae54\ub054\ud558\uac8c \ub5a8\uc5b4\uc9d1\ub2c8\ub2e4. \uc77c\ubc18\uc801\uc73c\ub85c $\\log 10^n = n$\uc774\ub77c\ub294 \uc131\uc9c8\uc744 \uae30\uc5b5\ud558\uba74, \uc8fc\uc5b4\uc9c4 \uc218\uc758 \ud06c\uae30\ub97c \uac00\ub2a0\ud558\ub294 \ub370 \ud070 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4. \uc774\uc81c \uc774 \uac1c\ub150\uc744 \ud65c\uc6a9\ud558\uc5ec \uc2e4\uc81c \ubb38\uc81c\ub97c \uc5b4\ub5bb\uac8c \ud574\uacb0\ud558\ub294\uc9c0 \ub2e8\uacc4\ubcc4\ub85c \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4.","\uc608\uc81c \ubb38\uc81c: $\\log 2 \\approx 0.3010$\uc77c \ub54c, $2^{10}$\uc758 \uac12\uc744 \uc0c1\uc6a9\ub85c\uadf8\ub97c \uc774\uc6a9\ud558\uc5ec \ucd94\uce21\ud574 \ubd05\uc2dc\ub2e4. \uba3c\uc800 $x = 2^{10}$\uc774\ub77c\uace0 \ud558\uba74, \uc591\ubcc0\uc5d0 \uc0c1\uc6a9\ub85c\uadf8\ub97c \ucde8\ud558\uc5ec $\\log x = \\log 2^{10}$\uc774 \ub429\ub2c8\ub2e4. \ub85c\uadf8\uc758 \uc131\uc9c8\uc5d0 \uc758\ud574 \uc9c0\uc218\ub294 \uc55e\uc73c\ub85c \ub0b4\ub824\uc62c \uc218 \uc788\uc73c\ubbc0\ub85c, $\\log x = 10 \\times \\log 2$\ub77c\ub294 \uc2dd\uc744 \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uc8fc\uc5b4\uc9c4 \uac12 $\\log 2 \\approx 0.3010$\uc744 \ub300\uc785\ud558\uc5ec \uacc4\uc0b0\ud558\uba74 $\\log x = 10 \\times 0.3010 = 3.010$\uc774 \ub429\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc815\uc218 \ubd80\ubd84\uc740 3\uc774\uace0 \uc18c\uc218 \ubd80\ubd84\uc740 0.010\uc785\ub2c8\ub2e4. \uc815\uc218 \ubd80\ubd84\uc774 3\uc774\ub77c\ub294 \uac83\uc740 $x$\uac00 4\uc790\ub9ac \uc218\uc784\uc744 \uc758\ubbf8\ud558\uba70, $\\log 1 = 0$\uc774\uace0 $\\log 2 = 0.3010$\uc774\ubbc0\ub85c \uc18c\uc218 \ubd80\ubd84 0.010\uc740 1\uacfc 2 \uc0ac\uc774\uc758 \uc5b4\ub5a4 \uc218\uc784\uc744 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \ub530\ub77c\uc11c $2^{10}$\uc740 1000\ubcf4\ub2e4 \uc870\uae08 \ud070 \uc218\uc784\uc744 \uc54c \uc218 \uc788\uc73c\uba70, \uc2e4\uc81c \uac12\uc778 1024\uc640 \uc77c\uce58\ud568\uc744 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),v3,B.o)],ai2),v3,B.o)],ai3),s3,s3,s3,"concept_\uc0c1\uc6a9\ub85c\uadf8",0,"","\ub300\uc218 > \ub85c\uadf8 > \ub85c\uadf8\uc758\uc131\uc9c8 > \uc0c1\uc6a9\ub85c\uadf8",b7,v3,s3)
b8=A.a(["\ubbf8\uc801\ubd84\u2160","\uc18d\ub3c4\uc640\uac00\uc18d\ub3c4","\uc18d\ub3c4"],ai0)
b8=A.av(s2,A.a([A.au(A.a(["\ubbf8\uc801\ubd84\u2160 > \uc18d\ub3c4\uc640\uac00\uc18d\ub3c4 > \uc18d\ub3c4 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.q,A.a(["\uc218\uc9c1\uc120 \uc704\ub97c \uc6c0\uc9c1\uc774\ub294 \uc810 $P$\uc758 \uc2dc\uac01 $t$\uc5d0\uc11c\uc758 \uc704\uce58\ub97c $x(t)$\ub77c\uace0 \ud560 \ub54c, \uc2dc\uac01 $t$\uc5d0\uc11c $t+\\Delta t$\uae4c\uc9c0\uc758 \uc704\uce58\uc758 \ubcc0\ud654\ub7c9\uc740 $x(t+\\Delta t) - x(t)$\uc785\ub2c8\ub2e4. \uc774\ub54c \ub2e8\uc704 \uc2dc\uac04\ub2f9 \uc704\uce58\uc758 \ubcc0\ud654\uc728\uc778 '\ud3c9\uade0\uc18d\ub3c4'\ub294 $\\frac{x(t+\\Delta t) - x(t)}{\\Delta t}$\ub85c \uc815\uc758\ub429\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc2dc\uac04\uc758 \uac04\uaca9 $\\Delta t$\ub97c \ud55c\uc5c6\uc774 $0$\uc5d0 \uac00\uae5d\uac8c \uc904\uc774\uba74, \ud2b9\uc815 \uc2dc\uac01 $t$\uc5d0\uc11c\uc758 \uc21c\uac04\uc801\uc778 \uc6c0\uc9c1\uc784\uc758 \uc815\ub3c4\ub97c \ub098\ud0c0\ub0b4\ub294 '\uc18d\ub3c4'\ub97c \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc18d\ub3c4 $v(t)$\ub294 \uc704\uce58 \ud568\uc218 $x(t)$\ub97c \uc2dc\uac01 $t$\uc5d0 \ub300\ud558\uc5ec \ubbf8\ubd84\ud558\uc5ec \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc989, \uc18d\ub3c4\ub294 \uc704\uce58\uc758 \uc2dc\uac04 \ubcc0\ud654\uc728\uc744 \uc758\ubbf8\ud558\uba70 \uc218\ud559\uc801\uc73c\ub85c \ub2e4\uc74c\uacfc \uac19\uc774 \uc815\uc758\ud569\ub2c8\ub2e4. $$v(t) = \\lim_{\\Delta t \\to 0} \\frac{x(t+\\Delta t) - x(t)}{\\Delta t} = \\frac{dx}{dt}$$ \uc18d\ub3c4\ub294 \ubc29\ud5a5\uc744 \uac00\uc9c0\ub294 \ubb3c\ub9ac\ub7c9\uc73c\ub85c, \uc218\uc9c1\uc120 \uc704\uc5d0\uc11c \uc591\uc758 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\uba74 \uc18d\ub3c4\ub294 \uc591($+$)\uc758 \uac12\uc744, \uc74c\uc758 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\uba74 \uc18d\ub3c4\ub294 \uc74c($-$)\uc758 \uac12\uc744 \uac16\uc2b5\ub2c8\ub2e4. \ubc18\uba74, \uc18d\ub3c4\uc758 \uc808\ub313\uac12\uc778 $|v(t)|$\ub294 '\uc18d\ub825'\uc774\ub77c\uace0 \ubd80\ub974\uba70, \uc774\ub294 \ubb3c\uccb4\uac00 \uc6c0\uc9c1\uc774\ub294 \ube60\ub974\uae30\ub9cc\uc744 \ub098\ud0c0\ub0c5\ub2c8\ub2e4.","\uc218\uc9c1\uc120 \uc704\ub97c \uc6c0\uc9c1\uc774\ub294 \uc810 $P$\uc758 \uc2dc\uac01 $t$\uc5d0\uc11c\uc758 \uc704\uce58\uac00 $x(t) = t^3 - 6t^2 + 9t$\ub77c\uace0 \ud560 \ub54c, \uc2dc\uac01 $t=4$\uc5d0\uc11c\uc758 \uc18d\ub3c4\ub97c \uad6c\ud558\ub294 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\uc2dc\ub2e4. \uc18d\ub3c4 $v(t)$\ub294 \uc704\uce58 $x(t)$\ub97c \ubbf8\ubd84\ud55c \uac83\uc774\ubbc0\ub85c, \ubbf8\ubd84\ubc95\uc758 \uae30\ubcf8 \uacf5\uc2dd\uc744 \uc801\uc6a9\ud558\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$v(t) = \\frac{d}{dt}(t^3 - 6t^2 + 9t) = 3t^2 - 12t + 9$$","\uc774\uc81c \uad6c\ud55c \uc18d\ub3c4 \ud568\uc218 $v(t) = 3t^2 - 12t + 9$\uc5d0 \uc2dc\uac01 $t=4$\ub97c \ub300\uc785\ud558\uc5ec \uc21c\uac04 \uc18d\ub3c4\ub97c \uacc4\uc0b0\ud569\ub2c8\ub2e4. $$v(4) = 3(4)^2 - 12(4) + 9 = 3(16) - 48 + 9 = 48 - 48 + 9 = 9$$ \ub530\ub77c\uc11c \uc2dc\uac01 $t=4$\uc77c \ub54c \uc810 $P$\uc758 \uc18d\ub3c4\ub294 $9$\uc785\ub2c8\ub2e4. \uc774\ub294 \uc810 $P$\uac00 \ud574\ub2f9 \uc2dc\uac01\uc5d0 \uc218\uc9c1\uc120\uc758 \uc591\uc758 \ubc29\ud5a5\uc73c\ub85c $9$\ub9cc\ud07c\uc758 \uc18d\ub3c4\ub85c \uc6c0\uc9c1\uc774\uace0 \uc788\uc74c\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4.","\ucd94\uac00\ub85c, \uc810 $P$\uac00 \uc6b4\ub3d9 \ubc29\ud5a5\uc744 \ubc14\uafb8\ub294 \uc21c\uac04\uc740 \uc18d\ub3c4 $v(t)$\uac00 $0$\uc774 \ub418\ub294 \uc9c0\uc810\uc785\ub2c8\ub2e4. \uc704 \uc608\uc81c\uc5d0\uc11c $3t^2 - 12t + 9 = 0$\uc744 \ud480\uba74 $3(t^2 - 4t + 3) = 0$\uc774 \ub418\uc5b4 $3(t-1)(t-3) = 0$\uc774 \ub429\ub2c8\ub2e4. \uc989, $t=1$\uacfc $t=3$\uc77c \ub54c \uc18d\ub3c4\uac00 $0$\uc774 \ub418\uba70, \uc774 \uc2dc\uc810\ub4e4\uc744 \uae30\uc900\uc73c\ub85c \uc810 $P$\ub294 \uc6b4\ub3d9 \ubc29\ud5a5\uc744 \ubc14\uafb8\uac8c \ub429\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ubbf8\ubd84\uc744 \uc774\uc6a9\ud558\uba74 \ubb3c\uccb4\uc758 \uc704\uce58 \ubcc0\ud654\ub97c \ub9e4\uc6b0 \uc815\ubc00\ud558\uac8c \ubd84\uc11d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),"\uc18d\ub3c4",B.o)],ai2),"\uc18d\ub3c4",B.o)],ai3),s3,s3,s3,"concept_\uc18d\ub3c4",0,"","\ubbf8\uc801\ubd84\u2160 > \uc18d\ub3c4\uc640\uac00\uc18d\ub3c4 > \uc18d\ub3c4",b8,"\uc18d\ub3c4",s3)
b9=A.a(["\uacf5\ud1b5\uc218\ud5591","\uacbd\uc6b0\uc758\uc218","\uc21c\uc5f4","\uc911\ubcf5\uc21c\uc5f4"],ai0)
b9=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5591 > \uacbd\uc6b0\uc758\uc218 > \uc21c\uc5f4 > \uc911\ubcf5\uc21c\uc5f4 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.q,A.a(["\uc911\ubcf5\uc21c\uc5f4\uc774\ub780 \uc11c\ub85c \ub2e4\ub978 $n$\uac1c\uc5d0\uc11c \uc911\ubcf5\uc744 \ud5c8\uc6a9\ud558\uc5ec $r$\uac1c\ub97c \ud0dd\ud574 \uc77c\ub82c\ub85c \ub098\uc5f4\ud558\ub294 \uac83\uc744 \ub9d0\ud569\ub2c8\ub2e4. \uc77c\ubc18\uc801\uc778 \uc21c\uc5f4\uacfc \ub2ec\ub9ac, \ud55c \ubc88 \uc120\ud0dd\ud55c \ub300\uc0c1\uc744 \ub2e4\uc2dc \uc120\ud0dd\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uac00\uc7a5 \ud070 \ud2b9\uc9d5\uc785\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \ube44\ubc00\ubc88\ud638\ub97c \uc124\uc815\ud560 \ub54c 0\ubd80\ud130 9\uae4c\uc9c0\uc758 \uc22b\uc790 10\uac1c \uc911 \ud558\ub098\ub97c \uace8\ub77c 4\uc790\ub9ac\ub97c \ucc44\uc6b0\ub294 \uacbd\uc6b0, \uac19\uc740 \uc22b\uc790\ub97c \uc5ec\ub7ec \ubc88 \uc0ac\uc6a9\ud560 \uc218 \uc788\uc73c\ubbc0\ub85c \uc774\ub294 \uc911\ubcf5\uc21c\uc5f4\uc758 \ub300\ud45c\uc801\uc778 \uc0ac\ub840\uac00 \ub429\ub2c8\ub2e4.","\uc11c\ub85c \ub2e4\ub978 $n$\uac1c\uc5d0\uc11c \uc911\ubcf5\uc744 \ud5c8\uc6a9\ud558\uc5ec $r$\uac1c\ub97c \ud0dd\ud558\ub294 \uc911\ubcf5\uc21c\uc5f4\uc758 \uc218\ub294 \uae30\ud638\ub85c $\\Pi$\ub97c \uc0ac\uc6a9\ud558\uc5ec $_n\\Pi_r$\uacfc \uac19\uc774 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \uac01 \uc790\ub9ac\uc5d0 \uc62c \uc218 \uc788\ub294 \uacbd\uc6b0\uc758 \uc218\uac00 \ubaa8\ub450 $n$\uac00\uc9c0\uc529\uc774\ubbc0\ub85c, \uc774\ub97c $r$\ubc88 \uacf1\ud558\uba74 \uc804\uccb4 \uacbd\uc6b0\uc758 \uc218\ub97c \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc911\ubcf5\uc21c\uc5f4\uc758 \ud575\uc2ec \uacf5\uc2dd\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$ _n\\Pi_r = n^r $$","\uc911\ubcf5\uc21c\uc5f4\uc758 \uc131\uc9c8\uc744 \uc774\ud574\ud560 \ub54c\ub294 '\uac01 \uc790\ub9ac\ub97c \ucc44\uc6b0\ub294 \uc120\ud0dd\uc9c0'\ub97c \uc0dd\uac01\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \uccab \ubc88\uc9f8 \uc790\ub9ac\uc5d0 \uc62c \uc218 \uc788\ub294 \uac83\uc774 $n$\uac00\uc9c0, \ub450 \ubc88\uc9f8 \uc790\ub9ac\ub3c4 $n$\uac00\uc9c0, \uc774\ub7f0 \uc2dd\uc73c\ub85c $r$\ubc88\uc9f8 \uc790\ub9ac\uae4c\uc9c0 \ubaa8\ub450 $n$\uac00\uc9c0\uc758 \uc120\ud0dd\uc9c0\uac00 \uc874\uc7ac\ud569\ub2c8\ub2e4. \uacf1\uc758 \ubc95\uce59\uc5d0 \ub530\ub77c \uc774\ub4e4\uc744 \ubaa8\ub450 \uacf1\ud558\uba74 $n \\times n \\times \\dots \\times n$ ($r$\ubc88 \uacf1\ud568)\uc774 \ub418\uc5b4 \uacf5\uc2dd $n^r$\uc774 \uc720\ub3c4\ub418\ub294 \uac83\uc785\ub2c8\ub2e4.","\uc608\uc81c \ubb38\uc81c: \uc11c\ub85c \ub2e4\ub978 3\uac1c\uc758 \uc6b0\uccb4\ud1b5\uc5d0 \uc11c\ub85c \ub2e4\ub978 4\ud1b5\uc758 \ud3b8\uc9c0\ub97c \ub123\ub294 \ubc29\ubc95\uc758 \uc218\ub97c \uad6c\ud574\ubd05\uc2dc\ub2e4. \ub2e8, \ud3b8\uc9c0\ub97c \ud558\ub098\ub3c4 \ubc1b\uc9c0 \ubabb\ud558\ub294 \uc6b0\uccb4\ud1b5\uc774 \uc788\uc5b4\ub3c4 \ub429\ub2c8\ub2e4. \uc774 \ubb38\uc81c\ub294 \uac01 \ud3b8\uc9c0\ub9c8\ub2e4 \ub4e4\uc5b4\uac08 \uc6b0\uccb4\ud1b5\uc744 \uc120\ud0dd\ud558\ub294 \uacfc\uc815\uc73c\ub85c \uc0dd\uac01\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub2e8\uacc4\ubcc4 \ud480\uc774: \uccab \ubc88\uc9f8 \ud3b8\uc9c0\ub294 3\uac1c\uc758 \uc6b0\uccb4\ud1b5 \uc911 \ud558\ub098\ub97c \uc120\ud0dd\ud560 \uc218 \uc788\uace0, \ub450 \ubc88\uc9f8 \ud3b8\uc9c0\ub3c4 3\uac1c \uc911 \ud558\ub098, \uc138 \ubc88\uc9f8\uc640 \ub124 \ubc88\uc9f8 \ud3b8\uc9c0\ub3c4 \uac01\uac01 3\uac1c \uc911 \ud558\ub098\ub97c \uc120\ud0dd\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc989, \ud3b8\uc9c0 4\ud1b5\uc774 \uac01\uac01 3\uac1c\uc758 \uc120\ud0dd\uc9c0\ub97c \uac00\uc9c0\ubbc0\ub85c \uc911\ubcf5\uc21c\uc5f4\uc758 \uac1c\ub150\uc744 \uc801\uc6a9\ud558\uba74 \ub429\ub2c8\ub2e4. $$ 3 \\times 3 \\times 3 \\times 3 = 3^4 = 81 $$ \ub530\ub77c\uc11c \ud3b8\uc9c0\ub97c \ub123\ub294 \ubc29\ubc95\uc740 \ucd1d 81\uac00\uc9c0\uc785\ub2c8\ub2e4.","\ub610 \ub2e4\ub978 \uc608\uc81c\ub85c, 0\uacfc 1 \ub450 \uac1c\uc758 \uc22b\uc790\ub9cc\uc744 \uc0ac\uc6a9\ud558\uc5ec \ub9cc\ub4e4 \uc218 \uc788\ub294 5\uc790\ub9ac \uc790\uc5f0\uc218\uc758 \uac1c\uc218\ub97c \uad6c\ud574\ubd05\uc2dc\ub2e4. \uccab \ubc88\uc9f8 \uc790\ub9ac\ub294 0\uc774 \uc62c \uc218 \uc5c6\uc73c\ubbc0\ub85c 1\ub9cc \uc62c \uc218 \uc788\uace0(1\uac00\uc9c0), \ub098\uba38\uc9c0 4\uac1c\uc758 \uc790\ub9ac\ub294 0\uacfc 1 \uc911 \uc544\ubb34\uac70\ub098 \uc62c \uc218 \uc788\uc73c\ubbc0\ub85c \uac01\uac01 2\uac00\uc9c0\uc529 \uc120\ud0dd \uac00\ub2a5\ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc804\uccb4 \uac1c\uc218\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$ 1 \\times 2 \\times 2 \\times 2 \\times 2 = 2^4 = 16 $$ \uc774\ucc98\ub7fc \uc911\ubcf5\uc21c\uc5f4\uc740 \ubb38\uc81c\uc758 \uc870\uac74\uc5d0 \ub530\ub77c \uccab \uc790\ub9ac\uc5d0 \uc81c\uc57d\uc774 \uc788\ub294 \uacbd\uc6b0 \ub4f1\uc744 \uace0\ub824\ud558\uc5ec \uc751\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),v4,B.o)],ai2),v4,B.o)],ai3),s3,s3,s3,"concept_\uc911\ubcf5\uc21c\uc5f4",0,"","\uacf5\ud1b5\uc218\ud5591 > \uacbd\uc6b0\uc758\uc218 > \uc21c\uc5f4 > \uc911\ubcf5\uc21c\uc5f4",b9,v4,s3)
c0=A.a(["\uacf5\ud1b5\uc218\ud5592","\ud568\uc218","\ud568\uc218\uc758\uc815\uc758","\ub300\uc751"],ai0)
c0=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5592 > \ud568\uc218 > \ud568\uc218\uc758\uc815\uc758 > \ub300\uc751 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.q,A.a(["\ub450 \uc9d1\ud569 $X$\uc640 $Y$\uac00 \uc788\uc744 \ub54c, \uc9d1\ud569 $X$\uc758 \uac01 \uc6d0\uc18c\uc5d0 \uc9d1\ud569 $Y$\uc758 \uc6d0\uc18c\ub97c \uc9dd\uc9c0\uc5b4 \uc8fc\ub294 \uac83\uc744 '\ub300\uc751'\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \uc6b0\ub9ac \ubc18 \ud559\uc0dd\ub4e4\uc758 \uc774\ub984\uc774 \uc801\ud78c \uc9d1\ud569 $X$\uc640 \uadf8\ub4e4\uc758 \ud608\uc561\ud615\uc774 \uc801\ud78c \uc9d1\ud569 $Y$\uac00 \uc788\ub2e4\uba74, \uac01 \ud559\uc0dd\uc5d0\uac8c \ud574\ub2f9\ud558\ub294 \ud608\uc561\ud615\uc744 \uc5f0\uacb0\ud558\ub294 \uac83\uc774 \ubc14\ub85c \ub300\uc751\uc785\ub2c8\ub2e4. \uc774\ub54c \uc9d1\ud569 $X$\ub97c \ub300\uc751\uc758 \uc2dc\uc791\uc810\uc778 '\uc815\uc758\uc5ed'\uacfc \uad00\ub828\ub41c \uc9d1\ud569\uc73c\ub85c, \uc9d1\ud569 $Y$\ub97c \ub300\uc751\uc758 \ub3c4\ucc29\uc810\uc778 '\uacf5\uc5ed'\uacfc \uad00\ub828\ub41c \uc9d1\ud569\uc73c\ub85c \uc0dd\uac01\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub300\uc751\uc740 \ud654\uc0b4\ud45c\ub97c \uc0ac\uc6a9\ud558\uc5ec \uc2dc\uac01\uc801\uc73c\ub85c \ub098\ud0c0\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc9d1\ud569 $X$\uc758 \uc6d0\uc18c $x$\uc5d0\uc11c \uc9d1\ud569 $Y$\uc758 \uc6d0\uc18c $y$\ub85c \ud654\uc0b4\ud45c\ub97c \uadf8\uc5b4 $x$\uac00 $y$\uc5d0 \ub300\uc751\ub428\uc744 \ud45c\ud604\ud558\uba70, \uc774\ub97c \uae30\ud638\ub85c $x \\longmapsto y$\uc640 \uac19\uc774 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \ub300\uc751\uc740 \ub2e8\uc21c\ud788 \uc9dd\uc744 \uc9d3\ub294 \ubaa8\ub4e0 \uad00\uacc4\ub97c \ud3ec\ud568\ud558\ub294 \ub113\uc740 \uac1c\ub150\uc73c\ub85c, \ub098\uc911\uc5d0 \ubc30\uc6b0\uac8c \ub420 '\ud568\uc218'\ub294 \uc774 \ub300\uc751 \uc911\uc5d0\uc11c '\uc9d1\ud569 $X$\uc758 \ubaa8\ub4e0 \uc6d0\uc18c\uac00 \uc9d1\ud569 $Y$\uc758 \uc6d0\uc18c\uc5d0 \uc624\uc9c1 \ud558\ub098\uc529\ub9cc \ub300\uc751\ub418\ub294 \ud2b9\ubcc4\ud55c \uaddc\uce59'\uc744 \uac00\uc9c4 \uac83\uc744 \ub9d0\ud569\ub2c8\ub2e4.","\ub300\uc751\uc758 \uc131\uc9c8\uc744 \uc774\ud574\ud558\uae30 \uc704\ud574 \uc9d1\ud569 $X = \\{1, 2, 3\\}$\uacfc $Y = \\{a, b, c, d\\}$\ub97c \uc608\ub85c \ub4e4\uc5b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. $1$\uc740 $a$\uc5d0, $2$\ub294 $b$\uc5d0, $3$\uc740 $c$\uc5d0 \ub300\uc751\uc2dc\ud0a4\ub294 \uac83\uacfc \uac19\uc774, \uc9d1\ud569 $X$\uc758 \uc6d0\uc18c\ub4e4\uc774 \uc9d1\ud569 $Y$\uc758 \uc6d0\uc18c \uc911 \ud558\ub098\ub97c \uc120\ud0dd\ud558\uc5ec \uc5f0\uacb0\ub418\ub294 \ubaa8\ub4e0 \uacbd\uc6b0\uc758 \uc218\uac00 \ub300\uc751\uc758 \uc608\uc2dc\uac00 \ub429\ub2c8\ub2e4. \ub300\uc751\uc5d0\uc11c\ub294 $X$\uc758 \ud55c \uc6d0\uc18c\uac00 $Y$\uc758 \uc5ec\ub7ec \uc6d0\uc18c\uc5d0 \ub300\uc751\ub420 \uc218\ub3c4 \uc788\uace0, $X$\uc758 \uc5b4\ub5a4 \uc6d0\uc18c\ub294 $Y$\uc758 \uc544\ubb34 \uc6d0\uc18c\uc640\ub3c4 \ub300\uc751\ub418\uc9c0 \uc54a\uc744 \uc218\ub3c4 \uc788\ub2e4\ub294 \uc810\uc774 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud480\uc5b4\ubd05\uc2dc\ub2e4. \ub450 \uc9d1\ud569 $X = \\{1, 2\\}$, $Y = \\{3, 4, 5\\}$\uac00 \uc788\uc744 \ub54c, \uc9d1\ud569 $X$\uc5d0\uc11c \uc9d1\ud569 $Y$\ub85c\uc758 \ub300\uc751 \uad00\uacc4\ub97c \ud558\ub098 \uc815\ud574\ubd05\uc2dc\ub2e4. '\uc9d1\ud569 $X$\uc758 \uc6d0\uc18c $x$\uc5d0 $x+2$\ub97c \ub354\ud55c \uac12\uc744 \ub300\uc751\uc2dc\ud0a8\ub2e4'\ub294 \uaddc\uce59\uc744 \uc801\uc6a9\ud558\uba74 \uc5b4\ub5bb\uac8c \ub420\uae4c\uc694? \uba3c\uc800 $x=1$\uc77c \ub54c, $1+2=3$\uc774\ubbc0\ub85c $1$\uc740 $3$\uc5d0 \ub300\uc751\ub429\ub2c8\ub2e4. \ub2e4\uc74c\uc73c\ub85c $x=2$\uc77c \ub54c, $2+2=4$\uc774\ubbc0\ub85c $2$\ub294 $4$\uc5d0 \ub300\uc751\ub429\ub2c8\ub2e4.","\uc704\uc758 \ub300\uc751\uc744 \uae30\ud638\ub85c \uc815\ub9ac\ud558\uba74 $1 \\longmapsto 3$ \uadf8\ub9ac\uace0 $2 \\longmapsto 4$\uac00 \ub429\ub2c8\ub2e4. \uc774 \uacfc\uc815\uc744 \uc9d1\ud569\uc758 \uc6d0\uc18c\ub85c \ud45c\ud604\ud558\uba74 \ub300\uc751 \uad00\uacc4\ub294 $\\{(1, 3), (2, 4)\\}$\uc640 \uac19\uc774 \uc21c\uc11c\uc30d\uc758 \uc9d1\ud569\uc73c\ub85c \ub098\ud0c0\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc5ec\uae30\uc11c $5$\ub294 \uc9d1\ud569 $X$\uc758 \uc5b4\ub5a4 \uc6d0\uc18c\uc640\ub3c4 \ub300\uc751\ub418\uc9c0 \uc54a\uc558\ub294\ub370, \ub300\uc751\uc758 \uc815\uc758\uc5d0\uc11c\ub294 \uc9d1\ud569 $Y$\uc758 \ubaa8\ub4e0 \uc6d0\uc18c\uac00 \ubc18\ub4dc\uc2dc \uc120\ud0dd\ubc1b\uc544\uc57c \ud560 \ud544\uc694\ub294 \uc5c6\uc73c\ubbc0\ub85c \uc774 \ub610\ud55c \uc62c\ubc14\ub978 \ub300\uc751\uc758 \uc0ac\ub840\uac00 \ub429\ub2c8\ub2e4."],ai0),"\ub300\uc751",B.o)],ai2),"\ub300\uc751",B.o)],ai3),s3,s3,s3,"concept_\ub300\uc751",0,"","\uacf5\ud1b5\uc218\ud5592 > \ud568\uc218 > \ud568\uc218\uc758\uc815\uc758 > \ub300\uc751",c0,"\ub300\uc751",s3)
c1=A.a(["\ubbf8\uc801\ubd84\u2160","\ud568\uc218\uc758\uadf9\ud55c","\uadf9\ud55c\uc758\uc815\uc758","\uc6b0\uadf9\ud55c"],ai0)
c1=A.av(s2,A.a([A.au(A.a(["\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uadf9\ud55c > \uadf9\ud55c\uc758\uc815\uc758 > \uc6b0\uadf9\ud55c \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.q,A.a(['[   "\ud568\uc218\uc758 \uadf9\ud55c\uc5d0\uc11c \'\uc6b0\uadf9\ud55c\'\uc774\ub780, \ubcc0\uc218 $x$\uac00 \uc5b4\ub5a4 \uac12 $a$\ubcf4\ub2e4 \ud070 \ucabd\uc5d0\uc11c $a$\uc5d0 \ud55c\uc5c6\uc774 \uac00\uae4c\uc6cc\uc9c8 \ub54c, \ud568\uc218 $f(x)$\uc758 \uac12\uc774 \uc77c\uc815\ud55c \uac12 $L$\uc5d0 \uac00\uae4c\uc6cc\uc9c0\ub294 \uc0c1\ud0dc\ub97c \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc989, \uc218\uc9c1\uc120 \uc704\uc5d0\uc11c $a$\uc758 \uc624\ub978\ucabd \ubc29\ud5a5\uc5d0\uc11c \uc67c\ucabd\uc73c\ub85c \ub2e4\uac00\uac00\ub294 \uacbd\uc6b0\ub97c \ub9d0\ud558\uba70, \uc774\ub97c \uae30\ud638\ub85c\ub294 $x \\\\to a+$\ub77c\uace0 \ud45c\ud604\ud569\ub2c8\ub2e4. \uc774\ub54c\uc758 \uadf9\ud55c\uac12\uc740 \ub2e4\uc74c\uacfc \uac19\uc774 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. $$ \\\\lim_{x \\\\to a+} f(x) = L $$",   "\uc6b0\uadf9\ud55c\uc744 \uc774\ud574\ud560 \ub54c \uac00\uc7a5 \uc911\uc694\ud55c \uc810\uc740 $x$\uac00 $a$\ubcf4\ub2e4 \ud070 \uac12\uc744 \uac00\uc9c0\uba74\uc11c $a$\ub85c \uc811\uadfc\ud55c\ub2e4\ub294 \uac83\uc785\ub2c8\ub2e4. \ub9cc\uc57d \ud568\uc218\uac00 $x=a$\uc5d0\uc11c \ub04a\uc5b4\uc838 \uc788\uac70\ub098, $x=a$\uc5d0\uc11c\uc758 \ud568\uc22b\uac12\uacfc \uc0c1\uad00\uc5c6\uc774 \uc624\ub978\ucabd\uc5d0\uc11c \ub2e4\uac00\uc624\ub294 \uadf8\ub798\ud504\uc758 \ub192\uc774\ub9cc \uad00\ucc30\ud558\uba74 \ub429\ub2c8\ub2e4. \ub9cc\uc57d $x$\uac00 $a$\uc5d0 \uac00\uae4c\uc6cc\uc9c8 \ub54c \ud568\uc218 $f(x)$\uc758 \uac12\uc774 \ubb34\ud55c\ud788 \ucee4\uc9c0\uac70\ub098 \uc791\uc544\uc9c0\uc9c0 \uc54a\uace0 \ud2b9\uc815\ud55c \uc2e4\uc218 $L$\uc5d0 \uc218\ub834\ud55c\ub2e4\uba74, \uc6b0\ub9ac\ub294 \uadf8 $L$\uc744 \uc6b0\uadf9\ud55c\uac12\uc774\ub77c\uace0 \uc815\uc758\ud569\ub2c8\ub2e4.",   "\uc6b0\uadf9\ud55c\uc758 \uc131\uc9c8\uc740 \uc77c\ubc18\uc801\uc778 \uadf9\ud55c\uc758 \uc131\uc9c8\uacfc \ub3d9\uc77c\ud569\ub2c8\ub2e4. \ub450 \ud568\uc218 $f(x)$\uc640 $g(x)$\uc5d0 \ub300\ud558\uc5ec \uc6b0\uadf9\ud55c\uc774 \uac01\uac01 \uc874\uc7ac\ud560 \ub54c, \uc0c1\uc218\ubc30, \ub367\uc148, \ube84\uc148, \uacf1\uc148, \ub098\ub217\uc148(\ub2e8, \ubd84\ubaa8\uc758 \uc6b0\uadf9\ud55c\uc774 0\uc774 \uc544\ub2d0 \ub54c)\uc5d0 \ub300\ud558\uc5ec \uac01\uac01\uc758 \uc6b0\uadf9\ud55c\uc744 \ub530\ub85c \uacc4\uc0b0\ud558\uc5ec \uc5f0\uc0b0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \ub450 \ud568\uc218\uc758 \ud569\uc758 \uc6b0\uadf9\ud55c\uc740 \uac01 \ud568\uc218\uc758 \uc6b0\uadf9\ud55c\uc758 \ud569\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$ \\\\lim_{x \\\\to a+} \\{f(x) + g(x)\\} = \\\\lim_{x\\\\to a+} f(x) + \\\\lim_{x\\\\to a+} g(x) $$",   "\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ud568\uc218 $f(x) = \\\\begin{cases} x+2 & (x \\\\ge 1) \\\\\\\\ 3x & (x < 1) \\\\end{cases}$\uc77c \ub54c, $x \\\\to 1+$\uc5d0\uc11c\uc758 \uc6b0\uadf9\ud55c\uc744 \uad6c\ud574\ubcf4\uc138\uc694. \uc6b0\uadf9\ud55c\uc740 $x$\uac00 1\ubcf4\ub2e4 \ud070 \ucabd\uc5d0\uc11c 1\ub85c \ub2e4\uac00\uac00\ub294 \uac83\uc774\ubbc0\ub85c, $x > 1$\uc77c \ub54c\uc758 \uc2dd\uc778 $f(x) = x+2$\ub97c \uc0ac\uc6a9\ud574\uc57c \ud569\ub2c8\ub2e4. \ub2e8\uacc4\ubcc4 \ud480\uc774\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uccab\uc9f8, $x > 1$\uc778 \uad6c\uac04\uc758 \ud568\uc218\uc2dd\uc744 \ud655\uc778\ud569\ub2c8\ub2e4. \ub458\uc9f8, \ud574\ub2f9 \uc2dd\uc5d0 $x=1$\uc744 \ub300\uc785\ud558\uc5ec \uadf9\ud55c\uac12\uc744 \uacc4\uc0b0\ud569\ub2c8\ub2e4. $$ \\\\lim_{x \\\\to 1+} f(x) = \\\\lim_{x \\\\to 1+} (x+2) = 1+2 = 3 $$",   "\ub610 \ub2e4\ub978 \uc608\uc81c\ub85c, \ubd84\uc218 \ud568\uc218 $f(x) = \\\\frac{|x-2|}{x-2}$\uc758 $x \\\\to 2+$\uc5d0\uc11c\uc758 \uc6b0\uadf9\ud55c\uc744 \uad6c\ud574\ubd05\uc2dc\ub2e4. \uc774 \ud568\uc218\ub294 $x$\uac00 2\ubcf4\ub2e4 \ud074 \ub54c\uc640 \uc791\uc744 \ub54c\uc758 \ud615\ud0dc\uac00 \ub2e4\ub985\ub2c8\ub2e4. $x > 2$\uc774\uba74 $x-2 > 0$\uc774\ubbc0\ub85c $|x-2| = x-2$\uac00 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc2dd\uc740 $f(x) = \\\\frac{x-2}{x-2} = 1$\uc774 \ub429\ub2c8\ub2e4. \uc774\ub97c \uadf9\ud55c\uc2dd\uc73c\ub85c \ub098\ud0c0\ub0b4\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$ \\\\lim_{x \\\\to 2+} \\\\frac{|x-2|}{x-2} = \\\\lim_{x \\\\to 2+} 1 = 1 $$ \uc774\ucc98\ub7fc \uc6b0\uadf9\ud55c\uc740 \uadf8\ub798\ud504\uc758 \uc624\ub978\ucabd\uc5d0\uc11c \ub2e4\uac00\uc624\ub294 \uacbd\ub85c\ub97c \ub530\ub77c \ud568\uc218\uac00 \ud5a5\ud558\ub294 \ubaa9\uc801\uc9c0\ub97c \ucc3e\ub294 \uacfc\uc815\uc784\uc744 \uae30\uc5b5\ud558\uba74 \uc27d\uac8c \ud574\uacb0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4." ]'],ai0),"\uc6b0\uadf9\ud55c",B.o)],ai2),"\uc6b0\uadf9\ud55c",B.o)],ai3),s3,s3,s3,"concept_\uc6b0\uadf9\ud55c",0,"","\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uadf9\ud55c > \uadf9\ud55c\uc758\uc815\uc758 > \uc6b0\uadf9\ud55c",c1,"\uc6b0\uadf9\ud55c",s3)
c2=A.a(["\uacf5\ud1b5\uc218\ud5591","\ubcf5\uc18c\uc218","\ucf24\ub808\ubcf5\uc18c\uc218"],ai0)
c2=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5591 > \ubcf5\uc18c\uc218 > \ucf24\ub808\ubcf5\uc18c\uc218 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.q,A.a(["\ubcf5\uc18c\uc218 $z = a + bi$ (\ub2e8, $a, b$\ub294 \uc2e4\uc218)\uc5d0 \ub300\ud558\uc5ec, \ud5c8\uc218\ubd80\ubd84\uc758 \ubd80\ud638\ub97c \ubc14\uafbc $a - bi$\ub97c $z$\uc758 \ucf24\ub808\ubcf5\uc18c\uc218\ub77c\uace0 \ud558\uba70, \uae30\ud638\ub85c\ub294 $\\bar{z}$\uc640 \uac19\uc774 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \ubcf5\uc18c\uc218 $3 + 2i$\uc758 \ucf24\ub808\ubcf5\uc18c\uc218\ub294 $3 - 2i$\uc774\uace0, $-1 - 5i$\uc758 \ucf24\ub808\ubcf5\uc18c\uc218\ub294 $-1 + 5i$\uc785\ub2c8\ub2e4. \uc2e4\uc218 \ubd80\ubd84\uc740 \uadf8\ub300\ub85c \ub450\uace0 \ud5c8\uc218 \ubd80\ubd84\uc758 \ubd80\ud638\ub9cc \ubc18\ub300\ub85c \ubc14\uafbc\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uc138\uc694.","\ucf24\ub808\ubcf5\uc18c\uc218\ub294 \uc0ac\uce59\uc5f0\uc0b0\uacfc \uad00\ub828\ud558\uc5ec \ub9e4\uc6b0 \uc720\uc6a9\ud55c \uc131\uc9c8\ub4e4\uc744 \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ub450 \ubcf5\uc18c\uc218 $z_1, z_2$\uc5d0 \ub300\ud558\uc5ec $\\overline{z_1 + z_2} = \\bar{z_1} + \\bar{z_2}$, $\\overline{z_1 - z_2} = \\bar{z_1} - \\bar{z_2}$, $\\overline{z_1 z_2} = \\bar{z_1} \\cdot \\bar{z_2}$, $\\overline{\\left(\\frac{z_1}{z_2}\\right)} = \\frac{\\bar{z_1}}{\\bar{z_2}}$ ($z_2 \\neq 0$)\uac00 \uc131\ub9bd\ud569\ub2c8\ub2e4. \ub610\ud55c, \uc5b4\ub5a4 \ubcf5\uc18c\uc218\uc640 \uadf8 \ucf24\ub808\ubcf5\uc18c\uc218\ub97c \ub354\ud558\uac70\ub098 \uacf1\ud558\uba74 \ud56d\uc0c1 \uc2e4\uc218\uac00 \ub41c\ub2e4\ub294 \uc911\uc694\ud55c \ud2b9\uc9d5\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc989, $z + \\bar{z} = 2a$\uc774\uace0 $z \\cdot \\bar{z} = a^2 + b^2$\uc785\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \ucf24\ub808\ubcf5\uc18c\uc218\ub97c \ud65c\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \uc54c\uc544\ubd05\uc2dc\ub2e4. \ubb38\uc81c: \ubcf5\uc18c\uc218 $z = 2 + i$\uc77c \ub54c, $z \\cdot \\bar{z}$\uc758 \uac12\uc744 \uad6c\ud558\uc2dc\uc624. \uba3c\uc800 $z = 2 + i$\uc774\ubbc0\ub85c, \uadf8 \ucf24\ub808\ubcf5\uc18c\uc218 $\\bar{z}$\ub294 \ud5c8\uc218 \ubd80\ubd84\uc758 \ubd80\ud638\ub97c \ubc14\uafbc $2 - i$\uac00 \ub429\ub2c8\ub2e4. \uc774\uc81c \ub450 \uc218\ub97c \uacf1\ud558\ub294 \uacfc\uc815\uc744 \ub2e8\uacc4\ubcc4\ub85c \uc218\ud589\ud569\ub2c8\ub2e4.","\ub2e8\uacc4\ubcc4 \ud480\uc774\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uacf1\uc148 \uc2dd\uc744 \uc138\uc6b0\uba74 $z \\cdot \\bar{z} = (2 + i)(2 - i)$\uc785\ub2c8\ub2e4. \uc774\ub97c \uc804\uac1c\ud558\uba74 $(2)^2 - (i)^2$\uc774 \ub418\ub294\ub370, \ubcf5\uc18c\uc218\uc758 \uc815\uc758\uc5d0 \ub530\ub77c $i^2 = -1$\uc784\uc744 \uc774\uc6a9\ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c $4 - (-1) = 4 + 1 = 5$\uac00 \ub429\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ubcf5\uc18c\uc218\uc640 \uadf8 \ucf24\ub808\ubcf5\uc18c\uc218\ub97c \uacf1\ud558\uba74 \ud56d\uc0c1 \ud5c8\uc218 \ub2e8\uc704 $i$\uac00 \uc0ac\ub77c\uc9c0\uace0 \uc2e4\uc218\uac00 \ub41c\ub2e4\ub294 \uc810\uc744 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),v5,B.o)],ai2),v5,B.o)],ai3),s3,s3,s3,"concept_\ucf24\ub808\ubcf5\uc18c\uc218",0,"","\uacf5\ud1b5\uc218\ud5591 > \ubcf5\uc18c\uc218 > \ucf24\ub808\ubcf5\uc18c\uc218",c2,v5,s3)
c3=A.a(["\uacf5\ud1b5\uc218\ud5592","\uc6d0\uc758\ubc29\uc815\uc2dd","\uc6d0\uc758\ud45c\uc900\ud615","\uc911\uc2ec"],ai0)
c3=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uc6d0\uc758\ubc29\uc815\uc2dd > \uc6d0\uc758\ud45c\uc900\ud615 > \uc911\uc2ec \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.q,A.a(["\uc6d0\uc758 \uc911\uc2ec\uc774\ub780 \uc6d0\uc744 \uad6c\uc131\ud558\ub294 \ubaa8\ub4e0 \uc810\uc73c\ub85c\ubd80\ud130 \uac19\uc740 \uac70\ub9ac\uc5d0 \uc788\ub294 \ud3c9\uba74 \uc704\uc758 \uace0\uc815\ub41c \uc810\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc6d0\uc758 \ubc29\uc815\uc2dd\uc5d0\uc11c \uc911\uc2ec\uc740 \uc6d0\uc758 \uc704\uce58\ub97c \uacb0\uc815\ud558\ub294 \uac00\uc7a5 \uc911\uc694\ud55c \uc694\uc18c\uc774\uba70, \uc88c\ud45c\ud3c9\uba74 \uc704\uc5d0\uc11c \uc6d0\uc758 \uc911\uc2ec\uc744 $(a, b)$\ub77c\uace0 \ud560 \ub54c, \uc911\uc2ec\uc73c\ub85c\ubd80\ud130\uc758 \uac70\ub9ac\uac00 \ubc18\uc9c0\ub984 $r$\uc778 \uc6d0\uc758 \ubc29\uc815\uc2dd\uc740 \ub2e4\uc74c\uacfc \uac19\uc740 \ud45c\uc900\ud615\uc73c\ub85c \ub098\ud0c0\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4. $$ (x - a)^2 + (y - b)^2 = r^2 $$ \uc774 \uc2dd\uc5d0\uc11c $x$\uc640 $y$\uc758 \uac12\uc5d0 \uac01\uac01 $a$\uc640 $b$\ub97c \ub300\uc785\ud558\uba74 \uc88c\ubcc0\uc774 $0$\uc774 \ub418\uc5b4 \ubc18\uc9c0\ub984\uc758 \uc81c\uacf1\uc778 $r^2$\uacfc \uac19\uc544\uc9c0\ubbc0\ub85c, \uc810 $(a, b)$\uac00 \uc6d0\uc758 \uc911\uc2ec\uc784\uc744 \uc27d\uac8c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc6d0\uc758 \ubc29\uc815\uc2dd\uc774 \uc77c\ubc18\ud615\uc778 $x^2 + y^2 + Ax + By + C = 0$\uc758 \ud615\ud0dc\ub85c \uc8fc\uc5b4\uc9c8 \ub54c\ub294, \uc644\uc804\uc81c\uacf1\uc2dd\uc744 \uc774\uc6a9\ud558\uc5ec \ud45c\uc900\ud615\uc73c\ub85c \ubcc0\ud615\ud574\uc57c \uc911\uc2ec\uc744 \ucc3e\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. $x$\ud56d\ub07c\ub9ac, $y$\ud56d\ub07c\ub9ac \ubb36\uc5b4 \uc815\ub9ac\ud558\uba74 $x^2 + Ax + (\frac{A}{2})^2$\uc640 $y^2 + By + (\frac{B}{2})^2$\uc758 \uaf34\uc744 \ub9cc\ub4e4 \uc218 \uc788\uc73c\uba70, \uc774\ub97c \ud1b5\ud574 \uc911\uc2ec\uc758 \uc88c\ud45c $(a, b)$\ub294 \ub2e4\uc74c\uacfc \uac19\uc774 \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. $$ a = -\frac{A}{2}, \\; b = -\frac{B}{2} $$ \uc989, \uc77c\ubc18\ud615\uc5d0\uc11c \uc911\uc2ec\uc758 \uc88c\ud45c\ub294 $x$\uc640 $y$\uc758 \uc77c\ucc28\ud56d \uacc4\uc218\ub97c \uac01\uac01 $-2$\ub85c \ub098\ub208 \uac12\uacfc \uac19\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \uc911\uc2ec\uc744 \ucc3e\uc544\ubd05\uc2dc\ub2e4. \ubc29\uc815\uc2dd $(x - 3)^2 + (y + 2)^2 = 16$\uc774 \ub098\ud0c0\ub0b4\ub294 \uc6d0\uc758 \uc911\uc2ec\uc744 \uad6c\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uc774 \uc2dd\uc740 \uc774\ubbf8 \ud45c\uc900\ud615\uc73c\ub85c \uc798 \uc815\ub9ac\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \ud45c\uc900\ud615\uc758 \uae30\ubcf8 \ud615\ud0dc\uc778 $(x - a)^2 + (y - b)^2 = r^2$\uacfc \ube44\uad50\ud574 \ubcf4\uba74, $a = 3$\uc774\uace0 $b = -2$\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc774 \uc6d0\uc758 \uc911\uc2ec\uc740 $(3, -2)$\uac00 \ub429\ub2c8\ub2e4.","\ub2e4\uc74c\uc73c\ub85c \uc77c\ubc18\ud615 \ubc29\uc815\uc2dd $x^2 + y^2 - 4x + 6y - 3 = 0$\uc758 \uc911\uc2ec\uc744 \uad6c\ud558\ub294 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 $x$\ud56d\uacfc $y$\ud56d\uc744 \ubaa8\uc544 \uc644\uc804\uc81c\uacf1\uc2dd\uc73c\ub85c \ub9cc\ub4ed\ub2c8\ub2e4. $(x^2 - 4x) + (y^2 + 6y) = 3$\uc5d0\uc11c, \uac01 \uad04\ud638 \uc548\uc5d0 \ud544\uc694\ud55c \uc0c1\uc218\ub97c \ub354\ud574\uc90d\ub2c8\ub2e4. $x^2 - 4x + 4$\uc640 $y^2 + 6y + 9$\ub97c \ub9cc\ub4e4\uae30 \uc704\ud574 \uc591\ubcc0\uc5d0 $4$\uc640 $9$\ub97c \ub354\ud558\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$ (x^2 - 4x + 4) + (y^2 + 6y + 9) = 3 + 4 + 9 $$ \uc774\ub97c \uc815\ub9ac\ud558\uba74 $(x - 2)^2 + (y + 3)^2 = 16$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc774 \uc6d0\uc758 \uc911\uc2ec\uc740 $(2, -3)$\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),"\uc911\uc2ec",B.o)],ai2),"\uc911\uc2ec",B.o)],ai3),s3,s3,s3,"concept_\uc911\uc2ec",0,"","\uacf5\ud1b5\uc218\ud5592 > \uc6d0\uc758\ubc29\uc815\uc2dd > \uc6d0\uc758\ud45c\uc900\ud615 > \uc911\uc2ec",c3,"\uc911\uc2ec",s3)
c4=A.a(["\ub300\uc218","\ub85c\uadf8\ud568\uc218","\ub85c\uadf8\ud568\uc218\uc758\uadf8\ub798\ud504"],ai0)
c4=A.av(s2,A.a([A.au(A.a(["\ub300\uc218 > \ub85c\uadf8\ud568\uc218 > \ub85c\uadf8\ud568\uc218\uc758\uadf8\ub798\ud504 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.q,A.a(["\ub85c\uadf8\ud568\uc218 $y = \\log_a x$ (\ub2e8, $a > 0, a \\neq 1$)\ub294 \uc9c0\uc218\ud568\uc218 $y = a^x$\uc758 \uc5ed\ud568\uc218\uc785\ub2c8\ub2e4. \uc774 \ud568\uc218\uc758 \uadf8\ub798\ud504\ub97c \uadf8\ub9ac\uae30 \uc704\ud574\uc11c\ub294 \uba3c\uc800 \uc815\uc758\uc5ed\uacfc \uce58\uc5ed\uc744 \uc774\ud574\ud574\uc57c \ud569\ub2c8\ub2e4. \ub85c\uadf8\uc758 \uc815\uc758\uc5d0 \uc758\ud574 \uc9c4\uc218 \uc870\uac74\uc778 $x > 0$\uc774 \ud56d\uc0c1 \uc131\ub9bd\ud574\uc57c \ud558\ubbc0\ub85c, \ub85c\uadf8\ud568\uc218\uc758 \uc815\uc758\uc5ed\uc740 \uc591\uc758 \uc2e4\uc218 \uc804\uccb4\uc758 \uc9d1\ud569\uc774\uba70, \uce58\uc5ed\uc740 \uc2e4\uc218 \uc804\uccb4\uc758 \uc9d1\ud569\uc785\ub2c8\ub2e4. \uadf8\ub798\ud504\ub294 \ud56d\uc0c1 \uc810 $(1, 0)$\uc744 \uc9c0\ub098\uba70, $y$\ucd95\uc744 \uc810\uadfc\uc120\uc73c\ub85c \uac00\uc9d1\ub2c8\ub2e4.","\ub85c\uadf8\ud568\uc218\uc758 \uadf8\ub798\ud504 \ubaa8\uc591\uc740 \ubc11 $a$\uc758 \uac12\uc5d0 \ub530\ub77c \uacb0\uc815\ub429\ub2c8\ub2e4. $a > 1$\uc77c \ub54c, $x$\uac12\uc774 \uc99d\uac00\ud558\uba74 $y$\uac12\ub3c4 \uc99d\uac00\ud558\ub294 \uc99d\uac00\ud568\uc218\uc758 \ud615\ud0dc\ub97c \ub760\uba70 \uadf8\ub798\ud504\ub294 \uc624\ub978\ucabd \uc704\ub85c \ud5a5\ud569\ub2c8\ub2e4. \ubc18\uba74, $0 < a < 1$\uc77c \ub54c, $x$\uac12\uc774 \uc99d\uac00\ud558\uba74 $y$\uac12\uc740 \uac10\uc18c\ud558\ub294 \uac10\uc18c\ud568\uc218\uc758 \ud615\ud0dc\ub97c \ub760\uba70 \uadf8\ub798\ud504\ub294 \uc624\ub978\ucabd \uc544\ub798\ub85c \ud5a5\ud569\ub2c8\ub2e4. \ub610\ud55c, $y = \\log_a x$\uc640 $y = \\log_{1/a} x$\uc758 \uadf8\ub798\ud504\ub294 $x$\ucd95\uc5d0 \ub300\ud558\uc5ec \uc11c\ub85c \ub300\uce6d\uc778 \uad00\uacc4\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.","\ub85c\uadf8\ud568\uc218\uc758 \uadf8\ub798\ud504\ub97c \ud3c9\ud589\uc774\ub3d9\ud558\uac70\ub098 \ub300\uce6d\uc774\ub3d9\ud558\uc5ec \ub354\uc6b1 \ub2e4\uc591\ud55c \ud615\ud0dc\ub97c \ub9cc\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, $y = \\log_a(x - p) + q$\uc758 \uadf8\ub798\ud504\ub294 $y = \\log_a x$\uc758 \uadf8\ub798\ud504\ub97c $x$\ucd95\uc758 \ubc29\ud5a5\uc73c\ub85c $p$\ub9cc\ud07c, $y$\ucd95\uc758 \ubc29\ud5a5\uc73c\ub85c $q$\ub9cc\ud07c \ud3c9\ud589\uc774\ub3d9\ud55c \uac83\uc785\ub2c8\ub2e4. \uc774\ub54c \uc810\uadfc\uc120\uc740 \uc6d0\ub798 $x=0$\uc774\uc5c8\uc73c\ub098 \ud3c9\ud589\uc774\ub3d9\uc5d0 \uc758\ud574 $x=p$\ub85c \ubcc0\ud558\uac8c \ub429\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc131\uc9c8\uc744 \uc774\uc6a9\ud558\uba74 \ubcf5\uc7a1\ud55c \ub85c\uadf8\ud568\uc218\uc758 \uadf8\ub798\ud504\ub3c4 \uc27d\uac8c \uadf8\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc608\uc81c: \ud568\uc218 $y = \\log_2(x - 1) + 3$\uc758 \uadf8\ub798\ud504\uc758 \uc810\uadfc\uc120\uc744 \uad6c\ud558\uace0, $x=5$\uc77c \ub54c\uc758 \ud568\uc22b\uac12\uc744 \uad6c\ud558\uc2dc\uc624. \uccab \ubc88\uc9f8 \ub2e8\uacc4\ub85c \uc810\uadfc\uc120\uc744 \ucc3e\uc2b5\ub2c8\ub2e4. \ub85c\uadf8\ud568\uc218 $y = \\log_a(x - p) + q$\uc5d0\uc11c \uc9c4\uc218 \uc870\uac74\uc778 $x - p > 0$\uc744 \ub9cc\uc871\ud574\uc57c \ud558\ubbc0\ub85c, $x - 1 > 0$\uc5d0\uc11c $x > 1$\uc785\ub2c8\ub2e4. \ub530\ub77c\uc11c \uadf8\ub798\ud504\uc758 \uc810\uadfc\uc120\uc740 $$x = 1$$\uc774 \ub429\ub2c8\ub2e4.","\ub450 \ubc88\uc9f8 \ub2e8\uacc4\ub85c $x=5$\uc77c \ub54c\uc758 \ud568\uc22b\uac12\uc744 \uacc4\uc0b0\ud569\ub2c8\ub2e4. \uc8fc\uc5b4\uc9c4 \uc2dd\uc5d0 $x=5$\ub97c \ub300\uc785\ud558\uba74 $$y = \\log_2(5 - 1) + 3$$\uc774 \ub429\ub2c8\ub2e4. \uc774\ub97c \uc815\ub9ac\ud558\uba74 $$y = \\log_2 4 + 3$$\uc774 \ub418\uba70, $\\log_2 4 = 2$\uc774\ubbc0\ub85c $$y = 2 + 3 = 5$$\uc785\ub2c8\ub2e4. \ub530\ub77c\uc11c $x=5$\uc77c \ub54c\uc758 \ud568\uc22b\uac12\uc740 $5$\uc785\ub2c8\ub2e4."],ai0),v6,B.o)],ai2),v6,B.o)],ai3),s3,s3,s3,"concept_\ub85c\uadf8\ud568\uc218\uc758\uadf8\ub798\ud504",0,"","\ub300\uc218 > \ub85c\uadf8\ud568\uc218 > \ub85c\uadf8\ud568\uc218\uc758\uadf8\ub798\ud504",c4,v6,s3)
